INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO6-2-u2-C1','soc',6,2,'u2',1,'시장과 시장경제 — 시장은 물건이나 서비스의 거래가 이루어지는 곳(장소와 상관없이 온라인 쇼핑도 시장), 가계는 살림을 꾸려 가는 생활 공동체, 기업은 이윤을 목적으로 생산·판매하는 조직(이윤 = 수입 − 비용) · 가격은 사람들이 필요로 하는 양과 기업이 제공하는 양을 함께 견주어 정해지고, 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식이 시장경제 — 자유로운 경쟁으로 더 좋은 품질의 물건을 살 수 있음',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],1),
('SO6-2-u2-C2','soc',6,2,'u2',2,'가계와 기업의 역할과 관계 — 가계는 기업의 생산 활동에 참여해 소득을 얻고 그 소득으로 소비하며 적은 비용으로 가장 큰 만족을 얻는 합리적 선택(기준을 정해 비교)을 하려 하고, 기업은 일자리를 제공하고 물건·서비스를 생산·판매해 이윤을 얻으며 급여 지급·연구·세금 납부를 함 · 가계와 기업은 시장에서 만나 서로 도움을 주고받아 어느 한쪽이 역할을 못하면 다른 쪽도 어려워짐 · 기업의 성장 노력은 품질 좋고 값싼 상품·일자리·나라 경제 발전으로 이어짐',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],2),
('SO6-2-u2-C3','soc',6,2,'u2',3,'근로자의 권리 보호 — 가계는 노동력을 제공하는 근로자로서 경제활동에 참여하고, 휴가·휴식 같은 권리가 지켜지지 않으면 근로자·기업·소비자 모두 어려워짐 · 근로자는 단체를 만들거나 가입하고, 근로 조건을 기업과 협의하고, 함께 단체로 행동할 수 있으며, 나라는 법과 제도(최저 임금 제도·육아 휴직 제도 등)로 이를 보호 — 노동력은 경제활동에서 중요하고 근로자와 기업은 서로 의존하기 때문',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],3),
('SO6-2-u2-C4','soc',6,2,'u2',4,'기업의 자유와 사회적 책임 — 헌법이 보장하는 기업의 자유로 기업을 세워 자유롭게 경쟁하고 무엇을 얼마나 생산할지 합리적으로 결정하며, 새 제품·일자리·나라 경제 발전으로 이어짐 · 지나친 경쟁은 환경 오염·담합(약속해 가격 올리기)·잘못된 정보·사업 방해를 낳으므로 정부가 바로잡고, 기업은 사회에 큰 영향을 미치므로 환경·사회·투명 경영 같은 사회적 책임을 다해야 함',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],4),
('SO6-2-u2-C5','soc',6,2,'u2',5,'경제성장의 뜻과 우리나라의 경제성장 과정 — 경제성장은 국가 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것(1인당 국민 총소득 = 국민이 일정 기간 생산 활동으로 받은 소득의 합 ÷ 인구수) · 일제의 식민 통치와 6·25 전쟁으로 폐허가 된 뒤 가계·기업·정부가 함께 노력해 1960년대 경공업 제품 수출 → 1970년대 중화학 공업 발달 → 1988년 서울 올림픽 대회 → 반도체·자동차 등 첨단 산업과 문화 콘텐츠로 빠르게 성장(한강의 기적)',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],5),
('SO6-2-u2-C6','soc',6,2,'u2',5,'경제성장이 우리 생활에 미친 영향 — 첨단 기술 발전으로 생산 속도·생산량이 늘고 생활이 편리해짐, 새 일자리와 소득 증가로 생활이 풍족해져 문화 산업(콘텐츠 산업)이 발달하고 다시 경제를 키움, 교육의 질이 높아지고 수준 높은 의료 혜택으로 기대 수명이 늘어남 — 삶의 질이 높아짐',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],6),
('SO6-2-u2-C7','soc',6,2,'u2',7,'빠른 경제성장으로 생긴 문제 — 무분별한 개발·오염 물질·쓰레기 증가로 환경 문제, 소득 차이가 커지는 빈부 격차(상대적 빈곤율), 필요보다 많이 쓰는 과소비와 자원 낭비, 임금·복지를 둘러싼 근로자와 기업의 노사 갈등이 생김 — 그대로 두면 갈등·빚·자원 부족으로 경제성장도 어려워짐',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],7),
('SO6-2-u2-C8','soc',6,2,'u2',7,'경제성장 문제의 해결과 함께하는 노력 — 경제가 지속적으로 발전하려면 문제를 해결해야 함 · 해결 방안은 평가 기준(실천할 수 있나·효과가 큰가·비용이 적게 드나 등)을 세워 점수를 매겨 견주고 실천 계획을 세움, 기준이 바뀌면 고르는 방안도 바뀜 · 정부는 제도·정책, 기업과 근로자는 소통, 시민 단체·개인도 노력 · 공유지의 비극(함께 쓰는 자원을 자기 이익만 생각해 쓰면 공동체 전체가 피해)을 막으려면 규칙과 공동의 이익을 생각하는 태도가 함께 필요',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],8),
('SO6-2-u2-C9','soc',6,2,'u2',9,'무역의 뜻과 무역이 이루어지는 까닭 — 무역은 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일, 사 오면 수입·팔면 수출(같은 거래도 어느 나라에서 보느냐에 따라 수입이자 수출), 고려 벽란도에서도 무역이 있었고 오늘날 드라마·예능 같은 서비스도 수출 · 나라마다 자연환경·자원·자본·기술이 달라 효율적으로 생산하는 것이 다르므로, 잘 만드는 것은 수출하고 구하기 어렵거나 더 좋고 값싼 것은 수입하면 두 나라 모두 이익(흑연 수입 → 배터리 수출)',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],9),
('SO6-2-u2-C10','soc',6,2,'u2',11,'무역이 이루어지는 다양한 모습 — 우리나라는 원유·천연가스·석탄 같은 천연자원을 주로 수입하고 발달한 기술로 반도체·자동차·석유 제품·무선 통신 기기를 만들어 수출(원유 ≠ 석유 제품) · 넓은 땅과 알맞은 기후의 나라는 농산물(쌀 등), 자원이 풍부한 나라는 자원(원유 등), 기술이 뛰어난 나라는 첨단 제품(백신·로봇)·문화 상품을 수출하고, 싱가포르처럼 항로 길목의 지리적 위치를 활용하기도 함 · 박람회에서 상품을 알리고 거래함',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],10),
('SO6-2-u2-C11','soc',6,2,'u2',12,'무역을 통한 상호 의존과 경쟁 — 여러 나라는 물자·기술을 주고받으며 서로 의존(여러 나라 부품으로 스마트폰, 광물 탐사 기술 협력)하고 첨단 기술 개발·다른 나라 시설 건설·더 나은 무역 환경(자동화 항만)을 두고 경쟁 · 수출이 늘면 산업 성장·일자리·소득 증가, 수입이 늘면 생활은 편리해지나 국내 기업이 어려워질 수 있어 관세(수입품에 매기는 세금)·수입 제한으로 국내 산업을 보호하기도 함 · 기업은 노동력·시장·관세 조건이 유리한 나라에서 생산하기도 하며, 값싸고 다양한 제품·일자리를 주지만 정당한 임금·환경 문제도 살펴야 함',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],11),
('SO6-2-u2-C12','soc',6,2,'u2',12,'기업 운영 계획 세우기 — 기업의 대표가 되어 대표 상품(물건이나 서비스)과 특징을 정하고, 상품이 필요할 만한 나라를 조사해 주요 수출국을 고르며, 사회적 책임을 다하는 목표와 근로자의 권리를 보호하는 노력(대화의 시간·성과급·휴가 보장)을 담아 기업 소개 잡지로 나타냄',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],12)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO6-2-u2-X01','soc',6,'u2',ARRAY['SO6-2-u2-C1']::text[],'시장은 물건을 사고파는 건물이 있는 곳만이라고 여겨 온라인 쇼핑·중고 거래 같은 곳은 시장이 아니라고 여긴다','거래가 이루어지면 장소와 상관없이 시장'),
('SO6-2-u2-X02','soc',6,'u2',ARRAY['SO6-2-u2-C1']::text[],'가격이 한쪽(사려는 양이나 내놓은 양 하나, 또는 한 기업의 뜻)만으로 정해진다고 여긴다','사려는 양과 내놓은 양을 함께 견줘요'),
('SO6-2-u2-X03','soc',6,'u2',ARRAY['SO6-2-u2-C1','SO6-2-u2-C2']::text[],'가계와 기업이 하는 일·얻는 것을 바꾸어 안다(가계가 이윤을, 기업이 소득을 얻는다 등)','가계 → 소득·소비 · 기업 → 생산·이윤'),
('SO6-2-u2-X04','soc',6,'u2',ARRAY['SO6-2-u2-C2']::text[],'가계와 기업이 서로 상관없이 따로 경제활동을 하거나, 한쪽이 역할을 못해도 다른 쪽은 괜찮다고 여긴다','고리 하나가 끊기면 흐름 전체가 멈춰요'),
('SO6-2-u2-X05','soc',6,'u2',ARRAY['SO6-2-u2-C2']::text[],'합리적 선택을 가장 비싼(또는 가장 싼) 것 고르기나 남 따라 하기로 여기고, 기준을 정해 비교하지 않는다','우리 가족의 기준 몇 가지로 견줘요'),
('SO6-2-u2-X06','soc',6,'u2',ARRAY['SO6-2-u2-C3']::text[],'근로자의 권리는 기업이 알아서 지켜 주므로 법과 제도가 필요 없다거나, 근로자는 기업과 협의하거나 단체로 행동할 수 없다고 여긴다','혼자 낸 목소리 vs 법이 보장한 권리'),
('SO6-2-u2-X07','soc',6,'u2',ARRAY['SO6-2-u2-C3','SO6-2-u2-C4','SO6-2-u2-C11']::text[],'근로자와 기업, 기업과 사회, 나라와 나라처럼 서로 의존하는 관계를 한쪽만의 일로 여긴다','한쪽이 어려우면 다른 쪽은?'),
('SO6-2-u2-X08','soc',6,'u2',ARRAY['SO6-2-u2-C4']::text[],'기업의 자유를 무엇이든 해도 되는 것(담합·거짓 광고·사업 방해·환경 오염도 자유)으로 여겨 사회적 책임을 놓친다','돛(자유)과 키(책임)를 함께'),
('SO6-2-u2-X09','soc',6,'u2',ARRAY['SO6-2-u2-C4']::text[],'기업의 사회적 책임 활동의 갈래(환경·사회·투명 경영)나 정부의 바로잡기 노력을 헷갈린다','환경 — 에너지·폐기물 · 사회 — 인권·지역 · 투명 경영 — 공정·윤리'),
('SO6-2-u2-X10','soc',6,'u2',ARRAY['SO6-2-u2-C5']::text[],'경제성장을 인구가 늘어나는 것이나 한 기업의 이윤이 느는 것으로 여기거나, 1인당 국민 총소득의 뜻을 헷갈린다','나라 전체의 생산·소득 → 경제 규모'),
('SO6-2-u2-X11','soc',6,'u2',ARRAY['SO6-2-u2-C5']::text[],'우리나라 경제성장 과정의 차례(경공업 → 중화학 공업 → 서울 올림픽 → 첨단·문화 산업)나 출발 조건(폐허·자원 부족)을 헷갈린다','가벼운 물건 → 무거운 공업 → 첨단'),
('SO6-2-u2-X12','soc',6,'u2',ARRAY['SO6-2-u2-C5','SO6-2-u2-C6','SO6-2-u2-C7']::text[],'경제성장의 한쪽 영향만 보거나(좋은 점만·문제만), 성장이 누군가 혼자의 노력으로 저절로 이루어졌다고 여긴다','좋아진 모습과 경고등을 함께'),
('SO6-2-u2-X13','soc',6,'u2',ARRAY['SO6-2-u2-C6']::text[],'경제성장이 생활에 준 영향의 갈래(첨단 기술·문화 산업·교육·의료)를 바꾸어 짝짓는다','기대 수명 → 의료 · 콘텐츠 → 문화 산업'),
('SO6-2-u2-X14','soc',6,'u2',ARRAY['SO6-2-u2-C7']::text[],'빠른 경제성장으로 생긴 문제의 갈래(환경·빈부 격차·과소비와 자원 낭비·노사 갈등)를 헷갈린다','무엇이 지나쳤나? 개발·소득 차이·씀씀이·임금'),
('SO6-2-u2-X15','soc',6,'u2',ARRAY['SO6-2-u2-C8']::text[],'해결 방안을 평가 기준 없이 느낌·먼저 낸 순서로 고르거나, 문제 해결을 한 주체(정부만·개인만)의 일로 여긴다','기준 → 점수 → 견주기 · 정부·기업·근로자·시민'),
('SO6-2-u2-X16','soc',6,'u2',ARRAY['SO6-2-u2-C8']::text[],'공유지의 비극을 모두가 아껴 써서 생기는 일로 알거나, 규칙만 있으면 태도는 필요 없다고 여긴다','함께 쓰는 자원을 나만 생각하며 쓰면?'),
('SO6-2-u2-X17','soc',6,'u2',ARRAY['SO6-2-u2-C9']::text[],'수입과 수출을 바꾸어 알거나, 같은 거래도 어느 나라에서 보느냐에 따라 수입·수출이 갈린다는 점을 놓친다','사 오면 수입 · 팔면 수출 — 누구 쪽에서?'),
('SO6-2-u2-X18','soc',6,'u2',ARRAY['SO6-2-u2-C9','SO6-2-u2-C10']::text[],'무역은 물건이 모자랄 때만 하거나 손에 잡히는 물건만 사고판다고 여겨, 나라마다 조건이 달라 잘 만드는 것을 바꾸어 서로 이익을 얻는 까닭을 놓친다','자연환경·자원·자본·기술의 차이'),
('SO6-2-u2-X19','soc',6,'u2',ARRAY['SO6-2-u2-C10']::text[],'나라의 조건과 무역의 모습을 맞지 않게 짝짓는다(우리나라가 원유를 수출한다, 원유와 석유 제품을 같은 것으로 안다 등)','우리나라 — 자원 수입 → 기술로 제품 수출'),
('SO6-2-u2-X20','soc',6,'u2',ARRAY['SO6-2-u2-C11']::text[],'무역에서의 상호 의존과 경쟁을 헷갈리거나, 관세·수입 제한·해외 생산의 한쪽 영향만 본다','함께 만들기 = 의존 · 먼저 차지하기 = 경쟁'),
('SO6-2-u2-X21','soc',6,'u2',ARRAY['SO6-2-u2-C12']::text[],'기업 운영 계획에서 이윤만 생각하고 수출국 조사·사회적 책임·근로자를 위한 노력을 빠뜨린다','상품 · 수출국 · 목표 · 노력 넷 다')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_soc_u2_L01_basic#1','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'mc','auto','물건이나 서비스의 거래가 이루어지는 곳을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"물건이나 서비스의 거래가 이루어지는 곳을 무엇이라고 하나요?","options":[{"t":"시장","correct":true},{"t":"가계","mis":"SO6-2-u2-X03"},{"t":"기업","mis":"SO6-2-u2-X03"},{"t":"이윤","mis":"SO6-2-u2-X03"}],"explanation":["거래가 이루어지는 곳이 시장이에요.","전통 시장·대형 할인점·문구점이 모두 시장이에요.","온라인 쇼핑도 시장이에요."]}'::jsonb),
('g6_2_soc_u2_L01_basic#2','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'mc','auto','시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직은 무엇인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X01']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직은 무엇인가요?","options":[{"t":"기업","correct":true},{"t":"가계","mis":"SO6-2-u2-X03"},{"t":"시장","mis":"SO6-2-u2-X01"},{"t":"서비스","mis":"SO6-2-u2-X03"}],"explanation":["기업은 이윤을 얻으려고 생산하고 판매해요.","이윤은 수입에서 비용을 뺀 금액이에요.","살림을 꾸려 가는 쪽은 가계예요."]}'::jsonb),
('g6_2_soc_u2_L01_basic#3','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'ox','auto','온라인 쇼핑몰에서 중고 물품을 사고파는 것도 시장에서 이루어지는 거래예요.',ARRAY['SO6-2-u2-X01']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"ox","stem":"온라인 쇼핑몰에서 중고 물품을 사고파는 것도 시장에서 이루어지는 거래예요.","answer":"O","reason_options":[{"t":"장소와 상관없이 물건이나 서비스의 거래가 이루어지는 곳은 모두 시장이기 때문에","correct":true},{"t":"시장은 물건을 사고파는 건물이 있어야만 하기 때문에","mis":"SO6-2-u2-X01"}],"mis":"SO6-2-u2-X01","explanation":["시장을 정하는 것은 장소가 아니라 거래예요.","온라인에서도 거래가 이루어져요.","그래서 온라인 쇼핑몰도 시장이에요."]}'::jsonb),
('g6_2_soc_u2_L01_basic#4','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'sa','auto','시장에서 경제활동을 함께하며 살림을 꾸려 가는 생활 공동체를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"sa","stem":"시장에서 경제활동을 함께하며 살림을 꾸려 가는 생활 공동체를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["가계"],"explanation":["함께 살림을 꾸려 가는 공동체예요.","우리 가족도 하나의 가계예요.","가계는 시장에서 물건을 사요."],"mis":"SO6-2-u2-X03"}'::jsonb),
('g6_2_soc_u2_L01_basic#5','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','사과 가게 수첩에서 ㉮처럼 사려는 사과만 늘고 시장에 나온 사과는 그대로라면 사과 가격은 어떻게 될까요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"사과 가게 수첩에서 ㉮처럼 사려는 사과만 늘고 시장에 나온 사과는 그대로라면 사과 가격은 어떻게 될까요?","options":[{"t":"지난주보다 비싸진다","correct":true},{"t":"지난주보다 싸진다","mis":"SO6-2-u2-X02"},{"t":"지난주와 같다","mis":"SO6-2-u2-X02"},{"t":"가격이 사라진다","mis":"SO6-2-u2-X02"}],"explanation":["사려는 양은 늘고 나온 양은 그대로예요.","사과를 사려는 사람끼리 경쟁해요.","그래서 가격이 비싸져요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb),
('g6_2_soc_u2_L01_basic#6','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','사과 가게 수첩에서 ㉰처럼 사려는 사과와 시장에 나온 사과가 똑같이 한 상자씩 늘면 가격은 어떻게 될까요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"사과 가게 수첩에서 ㉰처럼 사려는 사과와 시장에 나온 사과가 똑같이 한 상자씩 늘면 가격은 어떻게 될까요?","options":[{"t":"지난주와 같다","correct":true},{"t":"지난주보다 비싸진다","mis":"SO6-2-u2-X02"},{"t":"지난주보다 싸진다","mis":"SO6-2-u2-X02"},{"t":"알 수 없다","mis":"SO6-2-u2-X02"}],"explanation":["두 쪽이 똑같이 늘었어요.","두 양을 견주면 달라진 것이 없어요.","그래서 가격은 지난주와 같아요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb),
('g6_2_soc_u2_L01_basic#7','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','시장경제의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X04','SO6-2-u2-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"시장경제의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식","correct":true},{"t":"기업 한 곳이 정한 가격대로만 물건을 사는 방식","mis":"SO6-2-u2-X02"},{"t":"가계와 기업이 만나지 않고 저마다 만들어 쓰는 방식","mis":"SO6-2-u2-X04"},{"t":"가계만 시장에서 경제활동을 하는 방식","mis":"SO6-2-u2-X03"}],"explanation":["가계와 기업이 시장에서 만나요.","자유롭게 경쟁하며 경제활동을 해요.","이 방식이 시장경제예요."]}'::jsonb),
('g6_2_soc_u2_L01_basic#8','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','시장에서 이루어지는 자유로운 경쟁의 모습이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"시장에서 이루어지는 자유로운 경쟁의 모습이 아닌 것은 어느 것인가요?","options":[{"t":"한 기업이 정한 가격을 모두가 그대로 따른다","correct":true},{"t":"일자리를 얻으려고 다른 사람들과 경쟁한다","mis":"SO6-2-u2-X02"},{"t":"원하는 물건을 사려고 다른 사람들과 경쟁한다","mis":"SO6-2-u2-X02"},{"t":"기업이 더 좋은 물건을 만들려고 다른 기업과 경쟁한다","mis":"SO6-2-u2-X02"}],"explanation":["사람들은 일자리와 물건을 두고 경쟁해요.","기업은 더 팔고 더 좋게 만들려고 경쟁해요.","한 기업이 가격을 정하면 자유로운 경쟁이 아니에요."]}'::jsonb),
('g6_2_soc_u2_L01_basic#9','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'ox','auto','시장에서 상품의 가격은 기업이 시장에 내놓은 양 하나만으로 정해져요.',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"ox","stem":"시장에서 상품의 가격은 기업이 시장에 내놓은 양 하나만으로 정해져요.","answer":"X","reason_options":[{"t":"사람들이 필요로 하는 양과 기업이 제공하는 양을 함께 견주어 정해지기 때문에","correct":true},{"t":"파는 쪽이 원하는 대로 가격을 정하기 때문에","mis":"SO6-2-u2-X02"}],"mis":"SO6-2-u2-X02","explanation":["가격은 두 가지 양에 따라 정해져요.","사려는 양과 내놓은 양이에요.","한쪽만 봐서는 알 수 없어요."]}'::jsonb),
('g6_2_soc_u2_L01_basic#10','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',3,'error','auto','사과 가게 수첩을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"error","stem":"사과 가게 수첩을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「사려는 사람이 늘면 가격은 언제나 비싸져.」","correct":true,"mis_target":"SO6-2-u2-X02"},{"t":"민서 — 「㉯는 나온 사과가 많아져서 가격이 싸질 거야.」","mis":"SO6-2-u2-X02"},{"t":"태윤 — 「두 쪽을 함께 봐야 가격이 어떻게 될지 알 수 있어.」","mis":"SO6-2-u2-X02"}],"explanation":["㉰를 보면 사려는 사과가 늘어도 가격이 같아요.","나온 사과도 함께 늘었기 때문이에요.","가격은 두 쪽을 함께 견주어 정해져요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb),
('g6_2_soc_u2_L01_challenge#1','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',2,'sa','auto','기업이 물건을 팔아 얻은 수입에서 그것을 생산하는 데 든 비용을 뺀 금액을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"sa","stem":"기업이 물건을 팔아 얻은 수입에서 그것을 생산하는 데 든 비용을 뺀 금액을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["이윤"],"explanation":["수입 − 비용 = 이윤이에요.","기업은 이윤을 목적으로 해요.","가계가 얻는 것은 소득이에요."],"mis":"SO6-2-u2-X03"}'::jsonb),
('g6_2_soc_u2_L01_challenge#2','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',2,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"시장","r":"물건이나 서비스의 거래가 이루어지는 곳"},{"l":"가계","r":"함께 살림을 꾸려 가는 생활 공동체"},{"l":"기업","r":"이윤을 목적으로 생산·판매하는 조직"},{"l":"서비스","r":"사람들에게 즐거움이나 편리함을 주는 활동"}],"mis":"SO6-2-u2-X03","explanation":["시장은 거래가 이루어지는 곳이에요.","가계는 살림, 기업은 이윤이에요.","서비스는 손에 잡히지 않는 활동이에요."]}'::jsonb),
('g6_2_soc_u2_L01_challenge#3','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','사과 가게 수첩의 ㉯에서 사과 가격이 싸지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"사과 가게 수첩의 ㉯에서 사과 가격이 싸지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사려는 양은 그대로인데 시장에 나온 사과가 많아져서 팔려는 쪽끼리 경쟁하기 때문에","correct":true},{"t":"사과를 사려는 사람이 많아졌기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과 가게가 가격을 마음대로 정했기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과를 사려는 사람과 나온 사과가 똑같이 늘었기 때문에","mis":"SO6-2-u2-X02"}],"explanation":["㉯는 나온 사과만 늘었어요.","팔려는 쪽이 사려는 쪽보다 많아요.","그래서 가격이 싸져요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb),
('g6_2_soc_u2_L01_challenge#4','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','「사과 가격이 지난주와 같다」는 것만 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"「사과 가격이 지난주와 같다」는 것만 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사려는 양과 나온 양이 모두 그대로였을 수도, 똑같이 늘거나 줄었을 수도 있다","correct":true},{"t":"사과를 사려는 사람이 한 명도 늘지 않았다","mis":"SO6-2-u2-X02"},{"t":"시장에 나온 사과는 지난주와 꼭 같다","mis":"SO6-2-u2-X02"},{"t":"가격은 처음부터 정해져 있어 바뀌지 않는다","mis":"SO6-2-u2-X02"}],"explanation":["가격이 같다는 것은 두 쪽의 견줌이 같다는 뜻이에요.","두 쪽이 함께 늘었을 수도 있어요.","㉰가 그런 경우예요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb),
('g6_2_soc_u2_L01_challenge#5','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'ox','auto','기업들이 자유롭게 경쟁하면 소비자는 더 좋은 품질의 물건을 고를 수 있어요.',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"ox","stem":"기업들이 자유롭게 경쟁하면 소비자는 더 좋은 품질의 물건을 고를 수 있어요.","answer":"O","reason_options":[{"t":"기업들이 다른 기업보다 더 좋은 물건을 만들려고 노력하기 때문에","correct":true},{"t":"경쟁하면 기업이 하나만 남아 고를 필요가 없어지기 때문에","mis":"SO6-2-u2-X02"}],"mis":"SO6-2-u2-X02","explanation":["기업은 더 많이 팔려고 경쟁해요.","그래서 더 좋은 물건을 만들려고 해요.","소비자는 우수한 물건을 살 수 있어요."]}'::jsonb),
('g6_2_soc_u2_L01_challenge#6','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','우리나라 경제활동의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X04']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"우리나라 경제활동의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"가계와 기업이 시장에서 만나 자유롭게 경쟁하면서 경제활동을 한다","correct":true},{"t":"나라가 모든 물건의 가격과 생산량을 정한다","mis":"SO6-2-u2-X02"},{"t":"가계는 시장에 가지 않고 필요한 물건을 모두 집에서 만든다","mis":"SO6-2-u2-X04"},{"t":"기업끼리는 경쟁하지 않기로 약속한다","mis":"SO6-2-u2-X02"}],"explanation":["우리나라는 시장경제의 특징을 따라요.","가계와 기업이 시장에서 만나요.","자유롭게 경쟁하며 경제활동을 해요."]}'::jsonb),
('g6_2_soc_u2_L01_challenge#7','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'error','auto','시장을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X01']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"error","stem":"시장을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「건물이 없으니 온라인 쇼핑은 시장이 아니야.」","correct":true,"mis_target":"SO6-2-u2-X01"},{"t":"도윤 — 「문구점도 연필을 사고파니까 시장이야.」","mis":"SO6-2-u2-X01"},{"t":"세아 — 「전통 시장과 대형 할인점도 시장이야.」","mis":"SO6-2-u2-X01"}],"explanation":["시장은 거래가 이루어지는 곳이에요.","건물이 있든 없든 상관없어요.","온라인 쇼핑도 시장이에요."]}'::jsonb),
('g6_2_soc_u2_L01_challenge#8','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'mc','auto','어느 날 사과 농장에 우박이 내려 시장에 나온 사과가 크게 줄었어요. 사려는 사람의 수는 그대로일 때 생길 일과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"mc","stem":"어느 날 사과 농장에 우박이 내려 시장에 나온 사과가 크게 줄었어요. 사려는 사람의 수는 그대로일 때 생길 일과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사과 가격이 비싸진다 — 사려는 양에 비해 나온 사과가 적어 사려는 쪽끼리 경쟁하기 때문에","correct":true},{"t":"사과 가격이 싸진다 — 사과가 적으면 팔기 어렵기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과 가격이 그대로다 — 사려는 사람의 수가 그대로이기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과 가격이 비싸진다 — 농장 한 곳이 가격을 정하기 때문에","mis":"SO6-2-u2-X02"}],"explanation":["나온 사과가 줄었어요.","사려는 양은 그대로예요.","사려는 양이 더 많아지니 가격이 올라요."]}'::jsonb),
('g6_2_soc_u2_L01_challenge#9','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'mc','auto','시장경제에서 가격이 하는 역할을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"mc","stem":"시장경제에서 가격이 하는 역할을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"사려는 양과 내놓은 양의 차이를 보여 주어 가계와 기업이 무엇을 얼마나 사고 만들지 정하게 돕는다","correct":true},{"t":"기업이 원하는 이윤만큼 미리 정해 둔 숫자이다","mis":"SO6-2-u2-X02"},{"t":"나라가 정해 주어 해마다 똑같이 유지된다","mis":"SO6-2-u2-X02"},{"t":"사려는 사람의 수만 알려 준다","mis":"SO6-2-u2-X02"}],"explanation":["가격은 두 쪽의 양을 견주어 정해져요.","가격이 오르면 기업은 더 만들려고 해요.","가계는 가격을 보고 살지 말지 정해요."]}'::jsonb),
('g6_2_soc_u2_L01_challenge#10','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'essay','teacher','시장경제가 무엇인지 쓰고, 시장에서 이루어지는 자유로운 경쟁이 우리 생활에 주는 도움을 기업과 소비자의 쪽에서 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"essay","stem":"시장경제가 무엇인지 쓰고, 시장에서 이루어지는 자유로운 경쟁이 우리 생활에 주는 도움을 기업과 소비자의 쪽에서 하나씩 쓰세요.","answer_guide":{"answer":"예: 시장경제는 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식이다. 기업은 다른 기업보다 더 많이 팔려고 더 좋은 물건을 만들고 새로운 물건을 개발하려고 노력한다. 그래서 소비자는 품질이 더 좋은 물건을 여러 가지 가운데 골라 살 수 있다.","scoring_points":["시장경제의 뜻을 바르게 썼는가","기업 쪽의 경쟁 모습을 썼는가","소비자가 얻는 도움을 썼는가"]},"explanation":["가계와 기업이 자유롭게 경쟁해요.","기업은 더 좋은 물건을 만들어요.","소비자는 더 좋은 물건을 골라요."]}'::jsonb),
('g6_2_soc_u2_L02_basic#1','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'mc','auto','가계가 기업의 생산 활동에 참여하고 그 대가로 얻는 것은 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"가계가 기업의 생산 활동에 참여하고 그 대가로 얻는 것은 무엇인가요?","options":[{"t":"소득","correct":true},{"t":"이윤","mis":"SO6-2-u2-X03"},{"t":"세금","mis":"SO6-2-u2-X03"},{"t":"비용","mis":"SO6-2-u2-X03"}],"explanation":["가계는 기업에서 일해요.","그 대가로 소득을 얻어요.","이윤은 기업이 얻는 거예요."]}'::jsonb),
('g6_2_soc_u2_L02_basic#2','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'mc','auto','기업이 하는 일이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"기업이 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"함께 살림을 꾸려 가며 저축을 의논한다","correct":true},{"t":"근로자를 고용하고 급여를 준다","mis":"SO6-2-u2-X03"},{"t":"더 좋은 물건을 만들려고 연구한다","mis":"SO6-2-u2-X03"},{"t":"판매로 얻은 수익에 대해 나라에 세금을 낸다","mis":"SO6-2-u2-X03"}],"explanation":["기업은 생산·고용·연구·세금 납부를 해요.","살림을 꾸리는 것은 가계예요.","저축 의논도 가계의 모습이에요."]}'::jsonb),
('g6_2_soc_u2_L02_basic#3','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'ox','auto','가계는 소득을 생각하여 적은 비용으로 가장 큰 만족을 얻는 소비를 하려고 노력해요.',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"ox","stem":"가계는 소득을 생각하여 적은 비용으로 가장 큰 만족을 얻는 소비를 하려고 노력해요.","answer":"O","reason_options":[{"t":"정해진 소득 안에서 꼭 필요한 것을 골라야 하기 때문에","correct":true},{"t":"가계는 소득과 상관없이 마음대로 쓰기 때문에","mis":"SO6-2-u2-X05"}],"mis":"SO6-2-u2-X05","explanation":["소득에는 한계가 있어요.","그래서 따져 보고 골라요.","이것이 합리적 선택이에요."]}'::jsonb),
('g6_2_soc_u2_L02_basic#4','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'mc','auto','어느 가족의 하루에서 가계가 기업의 생산 활동에 참여하는 모습은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"어느 가족의 하루에서 가계가 기업의 생산 활동에 참여하는 모습은 어느 것인가요?","options":[{"t":"오전 10시 — 엄마와 아빠가 각자 일터에서 일한다","correct":true},{"t":"오후 5시 — 자동차를 살펴본다","mis":"SO6-2-u2-X03"},{"t":"오후 7시 — 저녁을 먹는다","mis":"SO6-2-u2-X03"},{"t":"오후 10시 — 저축을 의논한다","mis":"SO6-2-u2-X03"}],"explanation":["일터에서 일하는 것이 생산 활동 참여예요.","그 대가로 소득을 얻어요.","자동차를 살펴보는 것은 소비를 위한 모습이에요."],"asset":{"type":"passage","lines":["오전 10시 — 엄마와 아빠는 각자 일터에서 일한다.","오후 5시 — 가족이 자동차 판매점에서 자동차를 살펴본다.","오후 7시 — 가족이 모여 저녁을 먹는다.","오후 10시 — 엄마와 아빠가 저축에 관해 의논한다."],"title":"어느 가족의 하루"}}'::jsonb),
('g6_2_soc_u2_L02_basic#5','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'match','auto','가계와 기업이 주고받는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"match","stem":"가계와 기업이 주고받는 것을 알맞게 이으세요.","pairs":[{"l":"가계 → 기업","r":"일손(노동력)"},{"l":"기업 → 가계","r":"급여(소득)"},{"l":"기업 → 시장","r":"물건과 서비스"},{"l":"가계 → 시장","r":"물건값"}],"mis":"SO6-2-u2-X03","explanation":["가계는 일손을 주고 급여를 받아요.","기업은 물건과 서비스를 내놓아요.","가계는 물건값을 내고 소비해요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb),
('g6_2_soc_u2_L02_basic#6','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','네 고리 가운데 ①이 끊기면 어떤 일이 생길까요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"네 고리 가운데 ①이 끊기면 어떤 일이 생길까요?","options":[{"t":"기업이 생산에 필요한 일손을 얻지 못해 생산이 어려워진다","correct":true},{"t":"기업만 더 많은 이윤을 얻는다","mis":"SO6-2-u2-X04"},{"t":"가계가 소득을 더 많이 얻는다","mis":"SO6-2-u2-X04"},{"t":"다른 고리로 돌아 흐름이 그대로 이어진다","mis":"SO6-2-u2-X04"}],"explanation":["①은 가계가 기업에 일손을 주는 고리예요.","일손이 없으면 생산이 어려워요.","흐름은 끊긴 자리에서 멈춰요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb),
