('g6_2_soc_u2_L02_basic#8','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'ox','auto','자동차를 고르는 기준은 가족마다 다를 수 있어서 선택의 결과도 달라질 수 있어요.',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"ox","stem":"자동차를 고르는 기준은 가족마다 다를 수 있어서 선택의 결과도 달라질 수 있어요.","answer":"O","reason_options":[{"t":"가족마다 중요하게 생각하는 것이 다르기 때문에","correct":true},{"t":"합리적 선택의 답은 언제나 하나뿐이기 때문에","mis":"SO6-2-u2-X05"}],"mis":"SO6-2-u2-X05","explanation":["어떤 가족은 연비, 어떤 가족은 크기를 중요하게 여겨요.","기준이 다르면 고르는 것도 달라요.","그래도 기준을 정해 비교하는 것은 같아요."]}'::jsonb),
('g6_2_soc_u2_L02_basic#9','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','기업이 생산 시설을 늘리고 낡은 시설을 바꾸었을 때 소비자가 얻는 좋은 점은 어느 것인가요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X03','SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"기업이 생산 시설을 늘리고 낡은 시설을 바꾸었을 때 소비자가 얻는 좋은 점은 어느 것인가요?","options":[{"t":"품질이 좋은 상품을 더 저렴하게 살 수 있다","correct":true},{"t":"물건을 살 수 있는 곳이 사라진다","mis":"SO6-2-u2-X04"},{"t":"물건값을 내지 않아도 된다","mis":"SO6-2-u2-X03"},{"t":"물건을 고를 필요가 없어진다","mis":"SO6-2-u2-X02"}],"explanation":["생산 기술이 좋아지면 품질이 좋아져요.","많이 생산하면 값이 싸져요.","나라 경제가 발전하는 데도 도움이 돼요."]}'::jsonb),
('g6_2_soc_u2_L02_basic#10','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',3,'error','auto','가계와 기업의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"error","stem":"가계와 기업의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「기업이 문을 닫아도 가계는 아무 상관이 없어.」","correct":true,"mis_target":"SO6-2-u2-X04"},{"t":"나은 — 「기업이 어려워지면 가계는 소득을 얻기 어려워.」","mis":"SO6-2-u2-X04"},{"t":"시우 — 「가계와 기업은 시장에서 만나 도움을 주고받아.」","mis":"SO6-2-u2-X04"}],"explanation":["기업은 가계에 일자리를 줘요.","기업이 문을 닫으면 가계는 소득을 잃어요.","가계와 기업은 서로 이어져 있어요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb),
('g6_2_soc_u2_L02_challenge#1','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',2,'sa','auto','가계와 기업이 만나 서로 필요한 것을 주고받을 수 있게 해 주는 곳은 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"sa","stem":"가계와 기업이 만나 서로 필요한 것을 주고받을 수 있게 해 주는 곳은 어디인가요? 두 글자로 쓰세요.","answer":["시장"],"explanation":["가계와 기업은 시장에서 만나요.","물건·서비스·일손이 오가요.","시장은 형태가 다양해요."],"mis":"SO6-2-u2-X03"}'::jsonb),
