('g6_2_soc_u2_L02_challenge#3','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','자동차 비교표에서 ①과 ②의 별 합이 같아요. 이때 우리 가족이 「가격」을 가장 중요하게 여긴다면 고를 자동차와 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"자동차 비교표에서 ①과 ②의 별 합이 같아요. 이때 우리 가족이 「가격」을 가장 중요하게 여긴다면 고를 자동차와 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자동차 ① — 가장 중요한 가격 기준에서 별이 더 많기 때문에","correct":true},{"t":"자동차 ② — 크기 별이 가장 많기 때문에","mis":"SO6-2-u2-X05"},{"t":"자동차 ③ — 별의 합이 가장 적기 때문에","mis":"SO6-2-u2-X05"},{"t":"아무거나 — 합이 같으면 기준은 상관없기 때문에","mis":"SO6-2-u2-X05"}],"explanation":["합이 같으면 더 중요한 기준을 봐요.","가격 별은 ①이 3개, ②가 2개예요.","그래서 ①을 골라요."],"asset":{"type":"passage","lines":["우리 가족이 고른 기준 — 연비 · 크기 · 가격","자동차 ① — 연비 ★★★ · 크기 ★ · 가격 ★★★","자동차 ② — 연비 ★★ · 크기 ★★★ · 가격 ★★","자동차 ③ — 연비 ★ · 크기 ★★ · 가격 ★","별이 많을수록 그 기준에서 우리 가족에게 더 알맞다."],"title":"자동차 비교표"}}'::jsonb),
('g6_2_soc_u2_L02_challenge#4','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','네 고리 가운데 ④(기업이 가계에 급여를 준다)가 끊기면 흐름은 어떻게 될까요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"네 고리 가운데 ④(기업이 가계에 급여를 준다)가 끊기면 흐름은 어떻게 될까요?","options":[{"t":"가계가 소득을 얻지 못해 물건을 사지 못하고, 기업도 물건을 팔지 못해 함께 어려워진다","correct":true},{"t":"가계만 어려워지고 기업은 그대로다","mis":"SO6-2-u2-X04"},{"t":"기업만 어려워지고 가계는 그대로다","mis":"SO6-2-u2-X04"},{"t":"흐름이 다른 고리로 돌아 그대로 이어진다","mis":"SO6-2-u2-X04"}],"explanation":["급여가 끊기면 가계의 소득이 없어요.","소득이 없으면 물건을 사지 못해요.","그러면 기업도 이윤을 얻지 못해요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb),
('g6_2_soc_u2_L02_challenge#5','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'ox','auto','기업이 꾸준히 성장하면 일자리가 늘어나 가계에도 도움이 돼요.',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"ox","stem":"기업이 꾸준히 성장하면 일자리가 늘어나 가계에도 도움이 돼요.","answer":"O","reason_options":[{"t":"기업이 커지면 일할 사람이 더 필요해 가계가 소득을 얻을 기회가 늘기 때문에","correct":true},{"t":"기업이 성장하면 일할 사람이 필요 없어지기 때문에","mis":"SO6-2-u2-X04"}],"mis":"SO6-2-u2-X04","explanation":["기업이 커지면 일손이 더 필요해요.","일자리가 늘면 가계의 소득도 늘어요.","기업의 성장은 나라 경제에도 도움이 돼요."]}'::jsonb),
('g6_2_soc_u2_L02_challenge#6','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','기업이 더 많은 이윤을 얻으려고 하는 노력으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"기업이 더 많은 이윤을 얻으려고 하는 노력으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"근로자에게 약속한 급여를 주지 않는다","correct":true},{"t":"생산 시설에 투자해 생산량을 늘린다","mis":"SO6-2-u2-X03"},{"t":"생산 비용을 줄일 방법을 찾는다","mis":"SO6-2-u2-X03"},{"t":"판매량을 늘릴 방법을 찾는다","mis":"SO6-2-u2-X03"}],"explanation":["기업은 투자·비용 줄이기·판매 늘리기를 해요.","약속한 급여를 주지 않는 것은 바른 노력이 아니에요.","근로자는 기업의 소중한 짝이에요."]}'::jsonb),
('g6_2_soc_u2_L02_challenge#7','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'error','auto','합리적 선택을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"error","stem":"합리적 선택을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은우 — 「제일 비싼 자동차가 제일 좋으니까 그걸 사면 돼.」","correct":true,"mis_target":"SO6-2-u2-X05"},{"t":"라희 — 「모아 둔 돈으로 살 수 있는 것 중에서 골라야 해.」","mis":"SO6-2-u2-X05"},{"t":"지안 — 「우리 가족에게 중요한 기준을 정해서 비교해 보자.」","mis":"SO6-2-u2-X05"}],"explanation":["비싼 것이 꼭 알맞은 것은 아니에요.","소득 안에서 기준을 정해 비교해요.","그것이 합리적 선택이에요."],"asset":{"type":"passage","lines":["우리 가족이 고른 기준 — 연비 · 크기 · 가격","자동차 ① — 연비 ★★★ · 크기 ★ · 가격 ★★★","자동차 ② — 연비 ★★ · 크기 ★★★ · 가격 ★★","자동차 ③ — 연비 ★ · 크기 ★★ · 가격 ★","별이 많을수록 그 기준에서 우리 가족에게 더 알맞다."],"title":"자동차 비교표"}}'::jsonb),
('g6_2_soc_u2_L02_challenge#8','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'mc','auto','가계와 기업의 관계를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X04']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"mc","stem":"가계와 기업의 관계를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"기업은 가계에 일자리와 물건을 주고, 가계는 일손과 물건값을 주어 서로 없어서는 안 되는 관계이다","correct":true},{"t":"가계는 물건을 만들고 기업은 사서 쓰기만 하는 관계이다","mis":"SO6-2-u2-X03"},{"t":"가계와 기업은 서로 만나지 않는 관계이다","mis":"SO6-2-u2-X04"},{"t":"기업만 가계에 도움을 주는 한쪽의 관계이다","mis":"SO6-2-u2-X04"}],"explanation":["두 쪽은 서로 주고받아요.","한쪽이 멈추면 다른 쪽도 멈춰요.","그래서 서로 꼭 필요한 관계예요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb),
('g6_2_soc_u2_L02_challenge#9','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'mc','auto','어느 지역의 큰 공장이 문을 닫았어요. 그 뒤 그 지역의 식당과 가게 손님도 줄었어요. 이 일을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X02','SO6-2-u2-X05']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"mc","stem":"어느 지역의 큰 공장이 문을 닫았어요. 그 뒤 그 지역의 식당과 가게 손님도 줄었어요. 이 일을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"공장에서 일하던 가계가 소득을 잃어 소비가 줄자, 물건을 팔던 다른 기업들도 어려워졌다","correct":true},{"t":"공장과 식당은 서로 관계가 없어 우연히 함께 일어났다","mis":"SO6-2-u2-X04"},{"t":"식당이 가격을 올려서 생긴 일이다","mis":"SO6-2-u2-X02"},{"t":"가계가 저축을 하지 않아서 생긴 일이다","mis":"SO6-2-u2-X05"}],"explanation":["공장 → 가계의 급여가 끊겼어요.","가계는 소득이 줄어 덜 사요.","그러면 다른 기업도 어려워져요."]}'::jsonb),
('g6_2_soc_u2_L02_challenge#10','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'essay','teacher','시장경제에서 가계와 기업이 하는 일을 하나씩 쓰고, 둘 가운데 한쪽이 역할을 제대로 하지 못하면 어떤 일이 생기는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"essay","stem":"시장경제에서 가계와 기업이 하는 일을 하나씩 쓰고, 둘 가운데 한쪽이 역할을 제대로 하지 못하면 어떤 일이 생기는지 쓰세요.","answer_guide":{"answer":"예: 가계는 기업의 생산 활동에 참여해 소득을 얻고, 그 소득으로 기업이 만든 물건이나 서비스를 소비한다. 기업은 가계에 일자리를 주고 물건과 서비스를 생산하고 판매해 이윤을 얻는다. 만약 기업이 역할을 제대로 하지 못하면 가계는 소득을 얻지 못해 필요한 물건을 사기 어려워지고, 기업도 물건을 팔지 못해 함께 어려워진다.","scoring_points":["가계가 하는 일을 바르게 썼는가","기업이 하는 일을 바르게 썼는가","한쪽이 멈추면 다른 쪽도 어려워짐을 썼는가"]},"explanation":["가계 — 일하고 소득을 얻어 소비해요.","기업 — 일자리를 주고 생산해 이윤을 얻어요.","둘은 서로 이어져 있어요."]}'::jsonb),
('g6_2_soc_u2_L03_basic#1','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'mc','auto','가계는 기업에 무엇을 제공하는 근로자로서 경제활동에 참여하나요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"가계는 기업에 무엇을 제공하는 근로자로서 경제활동에 참여하나요?","options":[{"t":"노동력","correct":true},{"t":"이윤","mis":"SO6-2-u2-X03"},{"t":"세금","mis":"SO6-2-u2-X03"},{"t":"물건값","mis":"SO6-2-u2-X03"}],"explanation":["근로자는 기업에서 일해요.","일하는 힘이 노동력이에요.","기업은 그 대가로 급여를 줘요."]}'::jsonb),
('g6_2_soc_u2_L03_basic#2','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'mc','auto','우리나라가 근로자의 권리를 보호하려고 마련해 둔 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"우리나라가 근로자의 권리를 보호하려고 마련해 둔 것은 어느 것인가요?","options":[{"t":"법과 제도","correct":true},{"t":"벌금과 광고","mis":"SO6-2-u2-X06"},{"t":"관세와 무역","mis":"SO6-2-u2-X06"},{"t":"이윤과 가격","mis":"SO6-2-u2-X06"}],"explanation":["나라는 법과 제도로 근로자를 보호해요.","근로자는 그 위에서 성실히 일해요.","기업도 목표를 이룰 수 있어요."]}'::jsonb),
('g6_2_soc_u2_L03_basic#3','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'mc','auto','근로자의 권리를 보호하려고 우리나라가 실시하는 제도는 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"근로자의 권리를 보호하려고 우리나라가 실시하는 제도는 어느 것인가요?","options":[{"t":"최저 임금 제도","correct":true},{"t":"휴가를 줄이는 제도","mis":"SO6-2-u2-X06"},{"t":"휴게실을 닫는 제도","mis":"SO6-2-u2-X06"},{"t":"아파도 출근하게 하는 제도","mis":"SO6-2-u2-X06"}],"explanation":["최저 임금 제도는 임금의 가장 낮은 기준을 정해요.","육아 휴직 제도도 있어요.","모두 근로자를 보호하는 제도예요."]}'::jsonb),
('g6_2_soc_u2_L03_basic#4','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'ox','auto','근로자는 근로 조건이나 근로 환경에 관해 기업과 협의할 수 있어요.',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"ox","stem":"근로자는 근로 조건이나 근로 환경에 관해 기업과 협의할 수 있어요.","answer":"O","reason_options":[{"t":"법과 제도가 근로자가 기업과 협의할 권리를 보장하기 때문에","correct":true},{"t":"근로 조건은 기업만 정할 수 있기 때문에","mis":"SO6-2-u2-X06"}],"mis":"SO6-2-u2-X06","explanation":["근로자는 기업과 이야기를 나눌 수 있어요.","근무 시간이나 복지를 두고 협의해요.","법이 이 권리를 지켜 줘요."]}'::jsonb),
('g6_2_soc_u2_L03_basic#5','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'match','auto','근로자의 말과 그 말에 담긴 권리를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"match","stem":"근로자의 말과 그 말에 담긴 권리를 알맞게 이으세요.","pairs":[{"l":"근로자 ㉠","r":"근로 조건을 기업과 협의하는 권리"},{"l":"근로자 ㉡","r":"다른 근로자들과 함께 단체로 행동하는 권리"},{"l":"근로자 ㉢","r":"단체를 만들거나 가입하는 권리"}],"mis":"SO6-2-u2-X06","explanation":["㉠은 근무 시간을 회사와 이야기해요.","㉡은 함께 요청하자고 해요.","㉢은 근로자 단체에 가입했어요."],"asset":{"type":"speech","turns":[{"who":"근로자 ㉠","text":"근무 시간을 각자 사정에 맞게 조정할 수 있으면 좋겠어요. 회사와 이야기해 봐요."},{"who":"근로자 ㉡","text":"복지 혜택이 너무 부족해요. 우리 함께 늘려 달라고 요청합시다."},{"who":"근로자 ㉢","text":"더 나은 근로 조건을 만들려고 근로자 단체에 가입했어요."}]}}'::jsonb),
('g6_2_soc_u2_L03_basic#6','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','근로자 조사 기사에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자 조사 기사에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"휴가·휴식 같은 기본적인 권리조차 지켜지지 않는 근로자가 있다","correct":true},{"t":"모든 근로자가 휴가를 마음껏 썼다","mis":"SO6-2-u2-X06"},{"t":"근로자의 권리는 법이 없어도 잘 지켜진다","mis":"SO6-2-u2-X06"},{"t":"휴게실은 근로자의 권리와 관계가 없다","mis":"SO6-2-u2-X06"}],"explanation":["유급 휴가를 쓰지 못한 사람이 많았어요.","아파도 출근한 사람도 있었어요.","기본적인 권리가 지켜지지 않았어요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb),
('g6_2_soc_u2_L03_basic#7','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','근로자의 권리가 오래도록 지켜지지 않으면 생길 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자의 권리가 오래도록 지켜지지 않으면 생길 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"기업이 더 좋은 물건을 쉽게 만들게 된다","correct":true},{"t":"근로자의 일할 의욕이 낮아진다","mis":"SO6-2-u2-X07"},{"t":"근로자가 행복하게 일하기 힘들어진다","mis":"SO6-2-u2-X07"},{"t":"소비자가 그 기업의 물건을 사지 않으려 한다","mis":"SO6-2-u2-X07"}],"explanation":["일할 의욕이 낮으면 일을 잘하기 어려워요.","그러면 좋은 물건을 만들기도 어려워요.","소비자도 그 기업을 멀리할 수 있어요."]}'::jsonb),
('g6_2_soc_u2_L03_basic#8','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'ox','auto','근로자의 권리는 기업이 알아서 지켜 주므로 법과 제도는 필요하지 않아요.',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"ox","stem":"근로자의 권리는 기업이 알아서 지켜 주므로 법과 제도는 필요하지 않아요.","answer":"X","reason_options":[{"t":"조사 기사처럼 권리가 지켜지지 않는 일이 있어 법과 제도로 보호해야 하기 때문에","correct":true},{"t":"기업은 언제나 근로자의 권리를 먼저 생각하기 때문에","mis":"SO6-2-u2-X06"}],"mis":"SO6-2-u2-X06","explanation":["권리가 지켜지지 않는 근로자도 있어요.","그래서 법과 제도가 필요해요.","법은 근로자의 목소리를 받쳐 줘요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb),
('g6_2_soc_u2_L03_basic#9','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','근로자의 권리를 보호하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자의 권리를 보호하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"휴식을 보장하지 않는 기업을 칭찬한다","correct":true},{"t":"근로자에게 권리를 지키는 방법을 교육한다","mis":"SO6-2-u2-X06"},{"t":"근로자의 권리를 지키려고 노력하는 기업에 혜택을 준다","mis":"SO6-2-u2-X06"},{"t":"안전하게 일할 수 있는 환경을 마련한다","mis":"SO6-2-u2-X06"}],"explanation":["교육·혜택·안전한 환경은 좋은 방법이에요.","휴식을 보장하지 않는 기업은 바로잡아야 해요.","벌금을 물게 하는 방법도 있어요."]}'::jsonb),
('g6_2_soc_u2_L03_basic#10','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',3,'error','auto','근로자의 권리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"error","stem":"근로자의 권리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「근로자는 회사가 정한 대로만 해야 하고 단체를 만들 수 없어.」","correct":true,"mis_target":"SO6-2-u2-X06"},{"t":"유나 — 「근로자는 함께 단체로 행동하며 정당한 권리를 주장할 수 있어.」","mis":"SO6-2-u2-X06"},{"t":"하율 — 「육아 휴직 제도도 근로자를 보호하는 제도야.」","mis":"SO6-2-u2-X06"}],"explanation":["근로자는 단체를 만들거나 가입할 수 있어요.","함께 단체로 행동할 수도 있어요.","법과 제도가 이를 보장해요."]}'::jsonb),
('g6_2_soc_u2_L03_challenge#1','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',2,'sa','auto','휴가 기간에도 급여가 지급되는 휴가를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"sa","stem":"휴가 기간에도 급여가 지급되는 휴가를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["유급 휴가","유급휴가"],"explanation":["「유급」은 급여가 있다는 뜻이에요.","법이 일정 기간 일한 근로자에게 보장해요.","그런데도 못 쓰는 근로자가 있었어요."],"mis":"SO6-2-u2-X06"}'::jsonb),
('g6_2_soc_u2_L03_challenge#2','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',2,'mc','auto','근로자 ㉡처럼 「우리 함께 요청합시다」라고 말하는 것은 어떤 권리를 누리는 모습인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자 ㉡처럼 「우리 함께 요청합시다」라고 말하는 것은 어떤 권리를 누리는 모습인가요?","options":[{"t":"다른 근로자들과 함께 단체로 행동하는 권리","correct":true},{"t":"혼자서만 몰래 요청하는 권리","mis":"SO6-2-u2-X06"},{"t":"휴가를 스스로 포기하는 권리","mis":"SO6-2-u2-X06"},{"t":"기업을 대신해 가격을 정하는 권리","mis":"SO6-2-u2-X03"}],"explanation":["㉡은 함께 요청하자고 해요.","정당한 권리를 함께 주장하는 모습이에요.","법이 이 권리를 보장해요."],"asset":{"type":"speech","turns":[{"who":"근로자 ㉠","text":"근무 시간을 각자 사정에 맞게 조정할 수 있으면 좋겠어요. 회사와 이야기해 봐요."},{"who":"근로자 ㉡","text":"복지 혜택이 너무 부족해요. 우리 함께 늘려 달라고 요청합시다."},{"who":"근로자 ㉢","text":"더 나은 근로 조건을 만들려고 근로자 단체에 가입했어요."}]}}'::jsonb),
('g6_2_soc_u2_L03_challenge#3','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','근로자 한 사람이 혼자 요청할 때보다 법이 보장한 권리가 있을 때 협의가 더 잘 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X07']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"근로자 한 사람이 혼자 요청할 때보다 법이 보장한 권리가 있을 때 협의가 더 잘 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혼자 낸 목소리는 작지만 법이 보장한 권리가 근로자와 기업이 대등하게 마주 앉게 해 주기 때문에","correct":true},{"t":"법이 있으면 근로자의 요청은 무엇이든 받아들여지기 때문에","mis":"SO6-2-u2-X06"},{"t":"법이 있으면 기업이 약해져서 문을 닫기 때문에","mis":"SO6-2-u2-X07"},{"t":"혼자 요청해도 결과는 언제나 같기 때문에","mis":"SO6-2-u2-X06"}],"explanation":["근로자 한 사람은 기업보다 힘이 약해요.","법과 제도가 근로자의 목소리를 받쳐 줘요.","그래서 대등하게 협의할 수 있어요."]}'::jsonb),
('g6_2_soc_u2_L03_challenge#4','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','시장경제에서 근로자의 권리를 보호해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"시장경제에서 근로자의 권리를 보호해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근로자의 노동력은 경제활동에서 중요하고, 근로자와 기업은 서로 의존하는 관계이기 때문에","correct":true},{"t":"근로자와 기업은 서로 상관없이 따로 일하기 때문에","mis":"SO6-2-u2-X07"},{"t":"기업은 근로자 없이도 생산할 수 있기 때문에","mis":"SO6-2-u2-X07"},{"t":"근로자는 일을 하지 않아도 되기 때문에","mis":"SO6-2-u2-X06"}],"explanation":["기업이 생산하려면 노동력이 필요해요.","근로자는 기업에서 소득을 얻어요.","서로 기대고 있어서 권리 보호가 중요해요."]}'::jsonb),
('g6_2_soc_u2_L03_challenge#5','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'ox','auto','근로자가 권리를 보호받으면 근로자는 일을 성실히 하고, 기업도 원하는 목표를 이루기 쉬워져요.',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"ox","stem":"근로자가 권리를 보호받으면 근로자는 일을 성실히 하고, 기업도 원하는 목표를 이루기 쉬워져요.","answer":"O","reason_options":[{"t":"근로자가 안심하고 일하면 일할 의욕이 높아져 기업의 생산에도 도움이 되기 때문에","correct":true},{"t":"근로자의 권리를 지키면 기업은 반드시 손해를 보기 때문에","mis":"SO6-2-u2-X07"}],"mis":"SO6-2-u2-X07","explanation":["권리를 보호받으면 의욕이 높아져요.","좋은 물건과 서비스를 만들기 쉬워요.","근로자와 기업 모두에게 도움이 돼요."]}'::jsonb),
('g6_2_soc_u2_L03_challenge#6','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','유급 휴가를 법에서 보장하는데도 제대로 쓰지 못하는 근로자가 있는 까닭으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"유급 휴가를 법에서 보장하는데도 제대로 쓰지 못하는 근로자가 있는 까닭으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"근로자가 자기 권리를 잘 모르거나, 기업이 권리 보호에 소극적이기 때문에","correct":true},{"t":"유급 휴가는 법에 없는 휴가이기 때문에","mis":"SO6-2-u2-X06"},{"t":"근로자는 휴가가 필요 없기 때문에","mis":"SO6-2-u2-X06"},{"t":"휴가를 쓰면 반드시 일자리를 잃는다고 법에 적혀 있기 때문에","mis":"SO6-2-u2-X06"}],"explanation":["권리를 모르면 누리지 못해요.","기업이 소극적이면 쓰기 어려워요.","그래서 교육과 제도가 함께 필요해요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb),
('g6_2_soc_u2_L03_challenge#7','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'error','auto','근로자 조사 기사를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"error","stem":"근로자 조사 기사를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「근로자가 힘든 건 근로자만의 일이니 소비자와는 상관없어.」","correct":true,"mis_target":"SO6-2-u2-X07"},{"t":"봄이 — 「근로자가 행복하지 않으면 좋은 물건을 만들기도 어려워.」","mis":"SO6-2-u2-X07"},{"t":"가온 — 「근로자를 위한 휴게실을 쓰게 해야 해.」","mis":"SO6-2-u2-X06"}],"explanation":["근로자·기업·소비자는 이어져 있어요.","근로자가 힘들면 물건의 질도 떨어져요.","소비자도 그 기업을 멀리할 수 있어요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb),
('g6_2_soc_u2_L03_challenge#8','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'mc','auto','어느 회사가 「휴게실을 쓰지 말라」고 했고, 근로자들이 근로자 단체를 통해 회사와 이야기한 끝에 휴게실을 다시 쓰게 되었어요. 이 일에 담긴 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"mc","stem":"어느 회사가 「휴게실을 쓰지 말라」고 했고, 근로자들이 근로자 단체를 통해 회사와 이야기한 끝에 휴게실을 다시 쓰게 되었어요. 이 일에 담긴 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"근로자의 권리는 단체로 행동해야만 지켜지므로 협의는 쓸모가 없다","correct":true},{"t":"휴식은 근로자의 기본적인 권리이다","mis":"SO6-2-u2-X06"},{"t":"근로자는 단체를 통해 기업과 협의할 수 있다","mis":"SO6-2-u2-X06"},{"t":"법과 제도가 근로자의 목소리를 받쳐 준다","mis":"SO6-2-u2-X06"}],"explanation":["근로자는 단체를 통해 협의했어요.","협의로 문제를 풀었어요.","협의도 중요한 권리예요."]}'::jsonb),
('g6_2_soc_u2_L03_challenge#9','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'mc','auto','「최저 임금 제도」가 근로자와 시장경제 모두에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X06','SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"mc","stem":"「최저 임금 제도」가 근로자와 시장경제 모두에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근로자가 생활에 필요한 만큼의 소득을 얻으면 안심하고 일하고 소비할 수 있어 기업에도 도움이 되기 때문에","correct":true},{"t":"기업이 근로자를 더 이상 고용하지 않게 되기 때문에","mis":"SO6-2-u2-X07"},{"t":"근로자가 일하지 않아도 급여를 받기 때문에","mis":"SO6-2-u2-X06"},{"t":"물건값이 모두 같아지기 때문에","mis":"SO6-2-u2-X02"}],"explanation":["최저 임금은 소득의 바닥을 지켜요.","소득이 있으면 소비도 할 수 있어요.","가계와 기업은 이어져 있어요."]}'::jsonb),
('g6_2_soc_u2_L03_challenge#10','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'essay','teacher','근로자의 권리가 지켜지지 않는 상황을 하나 쓰고, 그 상황이 근로자·기업·소비자에게 어떤 영향을 주는지 쓴 뒤, 권리를 보호할 방법을 하나 제안하세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"essay","stem":"근로자의 권리가 지켜지지 않는 상황을 하나 쓰고, 그 상황이 근로자·기업·소비자에게 어떤 영향을 주는지 쓴 뒤, 권리를 보호할 방법을 하나 제안하세요.","answer_guide":{"answer":"예: 몸이 아파도 휴가를 쓰지 못하고 출근해야 하는 근로자가 있다. 근로자는 일할 의욕이 낮아져 행복하게 일하기 어렵고, 기업은 좋은 물건을 만들기 어려워지며, 소비자는 그 기업의 물건을 사지 않으려 할 수 있다. 그래서 근로자에게 권리를 알려 주는 교육을 하고, 휴가를 보장하지 않는 기업에는 벌금을 물게 하면 좋겠다.","scoring_points":["권리가 지켜지지 않는 상황을 썼는가","근로자·기업·소비자에게 주는 영향을 썼는가","알맞은 보호 방법을 제안했는가"]},"explanation":["권리가 무너지면 모두 어려워요.","근로자·기업·소비자는 이어져 있어요.","교육·제도·벌금·혜택을 떠올려요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb),
('g6_2_soc_u2_L04_basic#1','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','우리나라에서 기업이 누리는 경제활동의 자유로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라에서 기업이 누리는 경제활동의 자유로 알맞은 것은 어느 것인가요?","options":[{"t":"기업을 세워 다른 기업과 자유롭게 경쟁할 수 있다","correct":true},{"t":"다른 기업의 사업을 방해할 수 있다","mis":"SO6-2-u2-X08"},{"t":"소비자에게 잘못된 정보를 줄 수 있다","mis":"SO6-2-u2-X08"},{"t":"나라가 정해 준 상품만 만들 수 있다","mis":"SO6-2-u2-X02"}],"explanation":["우리나라는 헌법에서 기업의 자유를 보장해요.","기업을 세우고 자유롭게 경쟁해요.","방해나 거짓 정보는 자유가 아니에요."]}'::jsonb),
('g6_2_soc_u2_L04_basic#2','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','기업의 경제활동은 사회에 큰 영향을 미치므로 기업이 가져야 할 것은 무엇인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"기업의 경제활동은 사회에 큰 영향을 미치므로 기업이 가져야 할 것은 무엇인가요?","options":[{"t":"사회에 대한 책임감","correct":true},{"t":"이윤만 생각하는 마음","mis":"SO6-2-u2-X08"},{"t":"다른 기업을 이기려는 욕심","mis":"SO6-2-u2-X08"},{"t":"소비자를 속이는 꾀","mis":"SO6-2-u2-X08"}],"explanation":["기업의 활동은 많은 사람에게 영향을 줘요.","그래서 사회적 책임이 필요해요.","책임을 다하면 사회가 발전해요."]}'::jsonb),
('g6_2_soc_u2_L04_basic#3','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'ox','auto','기업은 어떤 상품을 얼마나 생산할지 자유롭게 정할 수 있어요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"ox","stem":"기업은 어떤 상품을 얼마나 생산할지 자유롭게 정할 수 있어요.","answer":"O","reason_options":[{"t":"기업은 이윤을 얻으려고 생산할 상품과 양을 합리적으로 결정할 자유가 있기 때문에","correct":true},{"t":"생산할 상품과 양은 소비자가 대신 정해 주기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["기업은 무엇을 얼마나 만들지 정해요.","적은 비용으로 큰 이윤을 얻으려 해요.","이것이 합리적 결정이에요."]}'::jsonb),
('g6_2_soc_u2_L04_basic#4','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓰는 기업이 중요하게 여기는 가치는 어느 것인가요?',ARRAY['SO6-2-u2-X09','SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓰는 기업이 중요하게 여기는 가치는 어느 것인가요?","options":[{"t":"환경","correct":true},{"t":"투명 경영","mis":"SO6-2-u2-X09"},{"t":"사회","mis":"SO6-2-u2-X09"},{"t":"담합","mis":"SO6-2-u2-X08"}],"explanation":["에너지를 효율적으로 쓰는 것은 환경을 위한 노력이에요.","폐기물 관리도 환경이에요.","담합은 가치가 아니라 문제예요."],"asset":{"type":"passage","lines":["환경 — 폐기물을 관리하고 에너지를 효율적으로 쓴다.","사회 — 사람들의 인권을 존중하고 소비자와 지역사회를 살핀다.","투명 경영 — 공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통한다."],"title":"기업이 중요하게 여기는 세 가치"}}'::jsonb),
('g6_2_soc_u2_L04_basic#5','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','기업 소식 다섯 가운데 기업이 사회적 책임을 다한 모습은 어느 것인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"기업 소식 다섯 가운데 기업이 사회적 책임을 다한 모습은 어느 것인가요?","options":[{"t":"㉤","correct":true},{"t":"㉠","mis":"SO6-2-u2-X08"},{"t":"㉡","mis":"SO6-2-u2-X08"},{"t":"㉢","mis":"SO6-2-u2-X08"}],"explanation":["㉤은 친환경 에너지를 써요.","㉠ 담합, ㉡ 오염, ㉢ 거짓 광고예요.","㉣ 사업 방해도 문제예요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb),
('g6_2_soc_u2_L04_basic#6','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','기업 소식 ㉠처럼 몇몇 회사가 몰래 약속해서 가격을 올리면 누가 가장 피해를 보나요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X02']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"기업 소식 ㉠처럼 몇몇 회사가 몰래 약속해서 가격을 올리면 누가 가장 피해를 보나요?","options":[{"t":"물건을 사는 소비자","correct":true},{"t":"약속한 회사들","mis":"SO6-2-u2-X08"},{"t":"가격을 정하는 나라","mis":"SO6-2-u2-X02"},{"t":"아무도 피해를 보지 않는다","mis":"SO6-2-u2-X08"}],"explanation":["경쟁하지 않고 함께 값을 올렸어요.","소비자는 비싼 값을 낼 수밖에 없어요.","그래서 정부가 이를 바로잡아요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb),
('g6_2_soc_u2_L04_basic#7','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'match','auto','기업의 노력과 그 노력이 지키려는 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"match","stem":"기업의 노력과 그 노력이 지키려는 가치를 알맞게 이으세요.","pairs":[{"l":"폐기물을 줄이고 재활용한다","r":"환경"},{"l":"지역 주민을 위한 도서관을 짓는다","r":"사회"},{"l":"근로자와 정기적으로 소통한다","r":"투명 경영"}],"mis":"SO6-2-u2-X09","explanation":["폐기물 관리는 환경이에요.","지역사회를 돕는 것은 사회예요.","공정·윤리·소통은 투명 경영이에요."],"asset":{"type":"passage","lines":["환경 — 폐기물을 관리하고 에너지를 효율적으로 쓴다.","사회 — 사람들의 인권을 존중하고 소비자와 지역사회를 살핀다.","투명 경영 — 공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통한다."],"title":"기업이 중요하게 여기는 세 가치"}}'::jsonb),
('g6_2_soc_u2_L04_basic#8','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'ox','auto','기업에 자유가 있으니 다른 기업의 사업을 방해해도 괜찮아요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"ox","stem":"기업에 자유가 있으니 다른 기업의 사업을 방해해도 괜찮아요.","answer":"X","reason_options":[{"t":"자유로운 경쟁은 공정해야 하고, 방해하면 다른 기업과 소비자가 피해를 보기 때문에","correct":true},{"t":"경쟁에서 이기는 것이 가장 중요하기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["기업의 자유에는 책임이 따라요.","방해는 공정한 경쟁이 아니에요.","정부가 이런 일을 바로잡아요."]}'::jsonb),
('g6_2_soc_u2_L04_basic#9','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','기업이 자유롭게 새 제품을 개발하고 생산하면 생기는 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X04']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"기업이 자유롭게 새 제품을 개발하고 생산하면 생기는 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"시장에 다양한 상품이 나오고 일자리가 늘어 나라 경제가 발전한다","correct":true},{"t":"시장에 상품이 하나만 남는다","mis":"SO6-2-u2-X02"},{"t":"일자리가 줄어든다","mis":"SO6-2-u2-X04"},{"t":"소비자가 고를 필요가 없어진다","mis":"SO6-2-u2-X02"}],"explanation":["기업이 자유로우면 성장하려고 노력해요.","다양한 상품과 일자리가 생겨요.","나라 경제가 발전해요."]}'::jsonb),
('g6_2_soc_u2_L04_basic#10','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',3,'error','auto','기업의 자유와 책임을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"error","stem":"기업의 자유와 책임을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「기업은 이윤을 얻으면 그만이니까 사회는 생각하지 않아도 돼.」","correct":true,"mis_target":"SO6-2-u2-X08"},{"t":"채아 — 「기업은 자유롭게 경쟁하지만 공정하게 해야 해.」","mis":"SO6-2-u2-X08"},{"t":"윤재 — 「사회적 책임을 다하는 기업이 늘면 사회가 발전해.」","mis":"SO6-2-u2-X08"}],"explanation":["기업의 활동은 사회에 큰 영향을 줘요.","이윤만 좇으면 여러 문제가 생겨요.","자유와 책임을 함께 가져야 해요."]}'::jsonb),
('g6_2_soc_u2_L04_challenge#1','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',2,'mc','auto','정부가 기업의 경제활동을 지원하는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X08','SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"정부가 기업의 경제활동을 지원하는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"기업이 새로운 기술과 제품을 개발하도록 도와준다","correct":true},{"t":"기업이 만들 상품을 모두 정해 준다","mis":"SO6-2-u2-X02"},{"t":"기업끼리 가격을 함께 올리게 돕는다","mis":"SO6-2-u2-X08"},{"t":"기업이 세금을 내지 않게 한다","mis":"SO6-2-u2-X03"}],"explanation":["정부는 새 기술 개발을 지원해요.","방해되는 제도를 고치기도 해요.","담합은 오히려 바로잡아야 해요."]}'::jsonb),
('g6_2_soc_u2_L04_challenge#2','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',2,'sa','auto','기업 소식 ㉠·㉡·㉢·㉣ 가운데 환경을 오염한 소식의 기호를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"sa","stem":"기업 소식 ㉠·㉡·㉢·㉣ 가운데 환경을 오염한 소식의 기호를 쓰세요.","answer":["㉡"],"explanation":["㉡은 폐수를 강에 흘려보냈어요.","이것은 환경 오염이에요.","㉠ 담합, ㉢ 거짓 광고, ㉣ 방해예요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"},"mis":"SO6-2-u2-X08"}'::jsonb),
('g6_2_soc_u2_L04_challenge#3','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','기업 소식 ㉢처럼 효과를 부풀린 광고를 막으려면 어떤 노력이 필요할까요?',ARRAY['SO6-2-u2-X09','SO6-2-u2-X08']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"기업 소식 ㉢처럼 효과를 부풀린 광고를 막으려면 어떤 노력이 필요할까요?","options":[{"t":"정부가 거짓이나 부풀린 광고를 하지 못하도록 규칙을 정하고 살핀다","correct":true},{"t":"기업이 광고를 더 많이 하게 돕는다","mis":"SO6-2-u2-X09"},{"t":"소비자가 광고를 믿고 그대로 사게 한다","mis":"SO6-2-u2-X08"},{"t":"광고는 기업의 자유이니 그냥 둔다","mis":"SO6-2-u2-X08"}],"explanation":["잘못된 정보는 소비자에게 피해를 줘요.","정부가 규칙을 정해 살펴요.","기업도 바른 정보를 줄 책임이 있어요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb),
('g6_2_soc_u2_L04_challenge#4','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','기업이 지나치게 경쟁할 때 생기는 문제를 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"기업이 지나치게 경쟁할 때 생기는 문제를 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"소비자나 다른 기업이 입을 피해는 생각하지 않고 이윤만 좇아 담합·오염·거짓 광고가 생길 수 있다","correct":true},{"t":"경쟁이 지나치면 상품의 품질이 언제나 좋아진다","mis":"SO6-2-u2-X08"},{"t":"경쟁이 지나치면 기업이 모두 같은 상품을 만들어 문제가 없다","mis":"SO6-2-u2-X08"},{"t":"지나친 경쟁은 소비자에게 언제나 이익이다","mis":"SO6-2-u2-X08"}],"explanation":["이윤만 좇으면 다른 사람의 피해를 놓쳐요.","담합·오염·거짓 광고·방해가 생겨요.","그래서 책임과 바로잡기가 필요해요."]}'::jsonb),
('g6_2_soc_u2_L04_challenge#5','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'ox','auto','기업이 사회적 책임을 다하면 경제가 성장하고 사회가 발전해요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"ox","stem":"기업이 사회적 책임을 다하면 경제가 성장하고 사회가 발전해요.","answer":"O","reason_options":[{"t":"환경을 지키고 소비자와 근로자를 살피는 기업이 늘면 사회 전체가 함께 좋아지기 때문에","correct":true},{"t":"사회적 책임은 기업의 이윤을 모두 없애기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["기업은 사회와 이어져 있어요.","책임을 다하면 믿음이 쌓여요.","경제와 사회가 함께 발전해요."]}'::jsonb),
('g6_2_soc_u2_L04_challenge#6','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','10대와 20대가 고루 좋아하는 제품을 알게 된 기업이 할 결정으로 가장 합리적인 것은 어느 것인가요?',ARRAY['SO6-2-u2-X09']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"10대와 20대가 고루 좋아하는 제품을 알게 된 기업이 할 결정으로 가장 합리적인 것은 어느 것인가요?","options":[{"t":"그 제품의 생산을 늘린다","correct":true},{"t":"아무도 찾지 않는 제품을 더 만든다","mis":"SO6-2-u2-X09"},{"t":"조사 결과와 상관없이 아무 제품이나 만든다","mis":"SO6-2-u2-X09"},{"t":"모든 제품의 생산을 멈춘다","mis":"SO6-2-u2-X09"}],"explanation":["많이 팔릴 제품을 더 만드는 것이 합리적이에요.","적은 비용으로 큰 이윤을 얻으려 해요.","주로 살 사람을 생각해 결정해요."]}'::jsonb),
('g6_2_soc_u2_L04_challenge#7','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'error','auto','기업이 중요하게 여기는 세 가치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X09']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"error","stem":"기업이 중요하게 여기는 세 가치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「근로자와 소통하는 건 환경을 지키는 노력이야.」","correct":true,"mis_target":"SO6-2-u2-X09"},{"t":"리안 — 「에너지를 아껴 쓰는 건 환경을 위한 노력이야.」","mis":"SO6-2-u2-X09"},{"t":"건우 — 「소비자를 보호하는 건 사회를 위한 노력이야.」","mis":"SO6-2-u2-X09"}],"explanation":["근로자와 소통은 투명 경영이에요.","에너지는 환경, 소비자 보호는 사회예요.","세 가치를 가려서 기억해요."],"asset":{"type":"passage","lines":["환경 — 폐기물을 관리하고 에너지를 효율적으로 쓴다.","사회 — 사람들의 인권을 존중하고 소비자와 지역사회를 살핀다.","투명 경영 — 공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통한다."],"title":"기업이 중요하게 여기는 세 가치"}}'::jsonb),
('g6_2_soc_u2_L04_challenge#8','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'mc','auto','배에 돛(자유)만 달고 키(책임)가 없으면 바위에 부딪히는 것에 빗대어 말할 때, 이 비유가 뜻하는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"mc","stem":"배에 돛(자유)만 달고 키(책임)가 없으면 바위에 부딪히는 것에 빗대어 말할 때, 이 비유가 뜻하는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기업이 자유롭게 빨리 나아가도 책임이 없으면 이윤만 좇다가 사회에 피해를 주어 결국 자신도 어려워진다","correct":true},{"t":"기업에 자유가 있으면 책임은 필요 없다","mis":"SO6-2-u2-X08"},{"t":"기업은 자유 없이 책임만 있어야 잘 나아간다","mis":"SO6-2-u2-X08"},{"t":"바위는 경쟁하는 다른 기업을 뜻한다","mis":"SO6-2-u2-X08"}],"explanation":["돛은 앞으로 나아가는 힘이에요.","키는 방향을 바르게 잡아요.","둘 다 있어야 항구에 닿아요."]}'::jsonb),
('g6_2_soc_u2_L04_challenge#9','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'mc','auto','작은 기업이 큰 기업과 공정하게 경쟁할 수 있도록 하는 노력이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X07']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"mc","stem":"작은 기업이 큰 기업과 공정하게 경쟁할 수 있도록 하는 노력이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공정한 경쟁이 있어야 여러 기업이 좋은 상품을 내놓아 소비자가 고를 수 있고 시장경제가 건강하게 돌아가기 때문에","correct":true},{"t":"큰 기업만 남아야 상품이 좋아지기 때문에","mis":"SO6-2-u2-X08"},{"t":"작은 기업은 경쟁하지 않아야 하기 때문에","mis":"SO6-2-u2-X08"},{"t":"경쟁은 소비자와 상관없기 때문에","mis":"SO6-2-u2-X07"}],"explanation":["큰 기업이 힘으로 누르면 경쟁이 사라져요.","경쟁이 사라지면 소비자가 손해예요.","공정한 경쟁이 시장경제를 지켜요."]}'::jsonb),
('g6_2_soc_u2_L04_challenge#10','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'essay','teacher','기업 소식 ㉠~㉣ 가운데 하나를 골라 어떤 문제가 있는지 쓰고, 그 문제를 해결하려면 정부와 기업이 각각 무엇을 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"essay","stem":"기업 소식 ㉠~㉣ 가운데 하나를 골라 어떤 문제가 있는지 쓰고, 그 문제를 해결하려면 정부와 기업이 각각 무엇을 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: ㉡은 공장에서 나온 폐수를 강에 몰래 흘려보내 환경을 오염했다. 정부는 환경을 오염한 기업에 벌금을 물리고, 환경을 오염하지 않는 것이 확인된 기업에 인증을 해 주면 좋겠다. 기업은 폐수를 깨끗하게 처리하는 시설을 갖추고 폐기물을 관리하는 사회적 책임을 다해야 한다.","scoring_points":["고른 소식의 문제를 바르게 썼는가","정부가 할 일을 썼는가","기업이 할 사회적 책임을 썼는가"]},"explanation":["지나친 경쟁은 문제를 낳아요.","정부는 바로잡고 지원해요.","기업은 사회적 책임을 다해요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb),
('g6_2_soc_u2_L05_basic#1','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'mc','auto','국가 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"국가 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것을 무엇이라고 하나요?","options":[{"t":"경제성장","correct":true},{"t":"시장경제","mis":"SO6-2-u2-X10"},{"t":"사회적 책임","mis":"SO6-2-u2-X10"},{"t":"무역","mis":"SO6-2-u2-X10"}],"explanation":["나라 전체의 생산과 소득이 늘어요.","경제 규모가 커져요.","이것이 경제성장이에요."]}'::jsonb),
('g6_2_soc_u2_L05_basic#2','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'mc','auto','세계가 우리나라의 빠른 경제성장을 부른 이름은 무엇인가요?',ARRAY['SO6-2-u2-X11','SO6-2-u2-X16']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"세계가 우리나라의 빠른 경제성장을 부른 이름은 무엇인가요?","options":[{"t":"한강의 기적","correct":true},{"t":"벽란도의 기적","mis":"SO6-2-u2-X11"},{"t":"공유지의 비극","mis":"SO6-2-u2-X16"},{"t":"지중해의 기적","mis":"SO6-2-u2-X11"}],"explanation":["폐허에서 빠르게 성장했어요.","세계가 놀랐어요.","그래서 「한강의 기적」이라 불러요."]}'::jsonb),
('g6_2_soc_u2_L05_basic#3','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'ox','auto','우리나라는 처음부터 자원과 자본이 넉넉해서 쉽게 경제성장을 이루었어요.',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"ox","stem":"우리나라는 처음부터 자원과 자본이 넉넉해서 쉽게 경제성장을 이루었어요.","answer":"X","reason_options":[{"t":"6·25 전쟁으로 산업 시설이 폐허가 되고 자원과 자본이 거의 없는 상태에서 성장했기 때문에","correct":true},{"t":"우리나라는 땅속 자원이 세계에서 가장 많기 때문에","mis":"SO6-2-u2-X11"}],"mis":"SO6-2-u2-X11","explanation":["전쟁으로 산업 시설이 무너졌어요.","자원과 자본도 거의 없었어요.","그런데도 빠르게 성장했어요."]}'::jsonb),
('g6_2_soc_u2_L05_basic#4','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',1,'mc','auto','경제가 성장하면서 의료 기술이 발달해 생긴 변화로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C6","difficulty":1,"kind":"mc","stem":"경제가 성장하면서 의료 기술이 발달해 생긴 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들의 기대 수명이 늘어났다","correct":true},{"t":"병원이 모두 사라졌다","mis":"SO6-2-u2-X13"},{"t":"기대 수명이 줄었다","mis":"SO6-2-u2-X13"},{"t":"의료 혜택을 받기 더 어려워졌다","mis":"SO6-2-u2-X13"}],"explanation":["치료하기 힘들던 병을 고칠 수 있게 됐어요.","수준 높은 의료 혜택을 받아요.","그래서 기대 수명이 늘었어요."]}'::jsonb),
('g6_2_soc_u2_L05_basic#5','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','우리나라 경제성장의 장면 ㉠~㉣을 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"우리나라 경제성장의 장면 ㉠~㉣을 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉠ → ㉣","correct":true},{"t":"㉢ → ㉡ → ㉠ → ㉣","mis":"SO6-2-u2-X11"},{"t":"㉠ → ㉡ → ㉢ → ㉣","mis":"SO6-2-u2-X11"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SO6-2-u2-X11"}],"explanation":["1960년대 경공업이 먼저예요.","1970년대 중화학 공업, 1988년 올림픽이에요.","오늘날 반도체와 문화 콘텐츠가 이어져요."],"asset":{"type":"passage","lines":["㉠ 1988년 서울 올림픽 대회를 열었다.","㉡ 1960년대 — 옷·신발·가발 같은 경공업 제품을 수출했다.","㉢ 1970년대 — 철강·배·석유 화학 같은 중화학 공업이 발달했다.","㉣ 오늘날 — 반도체·자동차와 음악·게임·웹툰이 세계로 나간다."],"title":"우리나라 경제성장의 장면(차례 섞음)"}}'::jsonb),
('g6_2_soc_u2_L05_basic#6','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','「1인당 국민 총소득」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"「1인당 국민 총소득」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 일정 기간 생산 활동에 참여한 대가로 받은 소득의 합을 인구수로 나눈 금액","correct":true},{"t":"한 나라에 사는 사람의 수","mis":"SO6-2-u2-X10"},{"t":"한 기업이 얻은 이윤의 합계","mis":"SO6-2-u2-X10"},{"t":"한 가계가 물건을 사는 데 쓴 돈","mis":"SO6-2-u2-X10"}],"explanation":["나라 사람들이 받은 소득을 모두 더해요.","그것을 인구수로 나눠요.","한 사람이 받은 소득을 어림할 수 있어요."]}'::jsonb),
('g6_2_soc_u2_L05_basic#7','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',2,'match','auto','경제성장 뒤 달라진 모습 카드와 그 카드가 들어갈 바구니를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"match","stem":"경제성장 뒤 달라진 모습 카드와 그 카드가 들어갈 바구니를 알맞게 이으세요.","pairs":[{"l":"카드 ①","r":"첨단 기술"},{"l":"카드 ②","r":"의료"},{"l":"카드 ③","r":"문화 산업"},{"l":"카드 ④","r":"교육"}],"mis":"SO6-2-u2-X13","explanation":["로봇 생산은 첨단 기술이에요.","병 치료는 의료, 드라마·웹툰은 문화 산업이에요.","학습 자료는 교육이에요."],"asset":{"type":"passage","lines":["① 공장에서 로봇이 쉬지 않고 물건을 만든다.","② 치료하기 힘들던 병을 고칠 수 있게 되었다.","③ 외국 사람들이 우리 드라마와 웹툰을 즐겨 본다.","④ 학교마다 컴퓨터와 다양한 학습 자료가 갖춰졌다.","⑤ 빅데이터 전문가 같은 새로운 직업이 생겼다.","⑥ 사람들의 기대 수명이 늘어났다."],"title":"경제성장 뒤 달라진 모습 카드"}}'::jsonb),
('g6_2_soc_u2_L05_basic#8','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',2,'ox','auto','경제가 성장해 사람들의 생활이 풍족해지면 문화에 관한 관심이 높아져 문화 산업이 발달해요.',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"ox","stem":"경제가 성장해 사람들의 생활이 풍족해지면 문화에 관한 관심이 높아져 문화 산업이 발달해요.","answer":"O","reason_options":[{"t":"소득이 늘어 여유가 생기면 영화·음악·게임 같은 문화를 더 즐기기 때문에","correct":true},{"t":"경제가 성장하면 문화 산업은 사라지기 때문에","mis":"SO6-2-u2-X13"}],"mis":"SO6-2-u2-X13","explanation":["일자리와 소득이 늘었어요.","생활에 여유가 생겼어요.","문화와 관련한 산업이 발달했어요."]}'::jsonb),
('g6_2_soc_u2_L05_basic#9','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','우리나라가 빠른 경제성장을 이룰 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"우리나라가 빠른 경제성장을 이룰 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가계와 기업, 정부가 함께 노력했기 때문에","correct":true},{"t":"정부 혼자서만 노력했기 때문에","mis":"SO6-2-u2-X12"},{"t":"기업만 노력했기 때문에","mis":"SO6-2-u2-X12"},{"t":"아무도 노력하지 않아도 저절로 성장했기 때문에","mis":"SO6-2-u2-X12"}],"explanation":["가계는 열심히 일하고 저축했어요.","기업은 생산하고 수출했어요.","정부는 계획을 세우고 도왔어요."]}'::jsonb),
('g6_2_soc_u2_L05_basic#10','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',3,'error','auto','두 나라의 1인당 국민 총소득 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"error","stem":"두 나라의 1인당 국민 총소득 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「우리나라는 처음부터 ○○ 나라보다 소득이 높았어.」","correct":true,"mis_target":"SO6-2-u2-X11"},{"t":"소은 — 「1980년까지는 두 나라가 크게 다르지 않았어.」","mis":"SO6-2-u2-X11"},{"t":"이든 — 「1980년 뒤로 우리나라 막대가 훨씬 빠르게 커졌어.」","mis":"SO6-2-u2-X11"}],"explanation":["1960년에는 ○○ 나라가 조금 더 높았어요.","1980년에는 비슷했어요.","그 뒤 우리나라가 급격하게 높아졌어요."],"asset":{"type":"passage","lines":["1인당 국민 총소득을 막대 크기로만 견준 표(금액 없음)","1960년 — 우리나라 ▮ · ○○ 나라 ▮▮","1980년 — 우리나라 ▮▮ · ○○ 나라 ▮▮","2000년 — 우리나라 ▮▮▮▮▮▮ · ○○ 나라 ▮▮▮","2020년 — 우리나라 ▮▮▮▮▮▮▮▮▮▮ · ○○ 나라 ▮▮▮▮"],"title":"두 나라의 1인당 국민 총소득"}}'::jsonb),
