('g6_2_soc_u2_L09_basic#7','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','사람들이 무역을 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"사람들이 무역을 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 나라 안에서 구하기 어려운 물자나 서비스를 이용하려고","correct":true},{"t":"한 나라 안에서 모든 물자를 쉽게 구할 수 있어서","mis":"SO6-2-u2-X18"},{"t":"다른 나라 물자는 모두 품질이 낮아서","mis":"SO6-2-u2-X18"},{"t":"나라마다 필요한 물자가 하나도 없어서","mis":"SO6-2-u2-X18"}],"explanation":["나라 안에 없는 것도 있어요.","다른 나라에서 사 와요.","그래서 무역을 해요."]}'::jsonb),
