('g6_2_soc_u2_L12_basic#3','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'ox','auto','수출이 늘어나면 더 많이 생산해야 하므로 산업이 성장하고 일자리와 소득이 늘어나요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"ox","stem":"수출이 늘어나면 더 많이 생산해야 하므로 산업이 성장하고 일자리와 소득이 늘어나요.","answer":"O","reason_options":[{"t":"팔 곳이 늘면 만들 것이 늘어 일할 사람과 소득도 함께 늘기 때문에","correct":true},{"t":"수출이 늘면 만들 것이 줄어들기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["수출 → 더 많이 생산해요.","산업이 성장해요.","일자리와 소득이 늘어요."]}'::jsonb),
('g6_2_soc_u2_L12_basic#4','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C12',1,'mc','auto','기업 운영 계획에서 대표 상품에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X21']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C12","difficulty":1,"kind":"mc","stem":"기업 운영 계획에서 대표 상품에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"물건뿐 아니라 배달 서비스 같은 서비스도 대표 상품이 될 수 있다","correct":true},{"t":"대표 상품은 손으로 만질 수 있는 물건만 된다","mis":"SO6-2-u2-X18"},{"t":"대표 상품은 다른 기업의 상품에서 고른다","mis":"SO6-2-u2-X21"},{"t":"대표 상품은 정하지 않아도 된다","mis":"SO6-2-u2-X21"}],"explanation":["게임도, 배달 서비스도 상품이에요.","우리 기업이 알리고 싶은 것을 정해요.","특징도 함께 정해요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb),
('g6_2_soc_u2_L12_basic#5','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','수입 철강에 높은 관세를 매긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"수입 철강에 높은 관세를 매긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라에서 만든 철강이 시장에서 경쟁력을 갖추게 하려고","correct":true},{"t":"수입 철강이 더 잘 팔리게 하려고","mis":"SO6-2-u2-X20"},{"t":"철강을 아무도 쓰지 않게 하려고","mis":"SO6-2-u2-X20"},{"t":"다른 나라와 무역을 모두 멈추려고","mis":"SO6-2-u2-X20"}],"explanation":["관세가 붙으면 수입 철강이 비싸져요.","우리 철강이 상대적으로 잘 팔려요.","그 사이 우리 제철소가 자랐어요."],"asset":{"type":"passage","lines":["예전 우리나라는 제철소를 막 짓기 시작했다.","외국의 값싼 철강이 많이 들어와 우리 제철소가 어려웠다.","정부는 수입 철강에 높은 관세를 매겼다.","오늘날 우리나라는 세계적인 철강 산업 국가가 되었다."],"title":"우리 철강 이야기"}}'::jsonb),
('g6_2_soc_u2_L12_basic#6','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','여러 나라가 자동화 항만 시스템을 갖추려고 하는 것은 무엇을 두고 하는 경쟁인가요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X16']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"여러 나라가 자동화 항만 시스템을 갖추려고 하는 것은 무엇을 두고 하는 경쟁인가요?","options":[{"t":"더 나은 무역 환경","correct":true},{"t":"쌀을 더 많이 기르는 것","mis":"SO6-2-u2-X20"},{"t":"다른 나라의 다리를 짓는 것","mis":"SO6-2-u2-X20"},{"t":"공동 어장의 물고기","mis":"SO6-2-u2-X16"}],"explanation":["항만은 배가 물건을 싣고 내리는 곳이에요.","빠르고 편리할수록 배가 모여요.","무역 환경을 두고 경쟁해요."]}'::jsonb),
('g6_2_soc_u2_L12_basic#7','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','베트남으로 가는 기업에 나온 조건 가운데 베트남의 위치와 관계있는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"베트남으로 가는 기업에 나온 조건 가운데 베트남의 위치와 관계있는 것은 어느 것인가요?","options":[{"t":"큰 시장인 중국과 국경을 맞대고 있다","correct":true},{"t":"노동력이 비교적 저렴하다","mis":"SO6-2-u2-X20"},{"t":"베트남 제품에 낮은 관세를 매기기로 약속한 나라가 많다","mis":"SO6-2-u2-X20"},{"t":"공장을 짓는 기업이 많다","mis":"SO6-2-u2-X20"}],"explanation":["국경을 맞댄 것은 위치예요.","만든 물건을 가까운 큰 시장에 보내기 쉬워요.","노동력·관세는 다른 조건이에요."],"asset":{"type":"passage","lines":["여러 외국 기업이 베트남에 공장을 짓고 있다.","· 노동력이 비교적 저렴하다.","· 큰 시장인 중국과 국경을 맞대고 있다.","· 베트남 제품에 낮은 관세를 매기기로 약속한 나라가 많다."],"title":"베트남으로 가는 기업"}}'::jsonb),
