('g6_2_soc_u2_review_c#8','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',1,'ox','auto','세계 여러 나라는 무역을 통해 물자와 기술을 주고받으며 서로 의존해요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"ox","stem":"세계 여러 나라는 무역을 통해 물자와 기술을 주고받으며 서로 의존해요.","answer":"O","reason_options":[{"t":"한 나라가 모든 것을 다 만들 수 없어 서로 필요한 것을 나누기 때문에","correct":true},{"t":"나라마다 필요한 것을 모두 스스로 만들기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["부품·자원·기술이 오가요.","서로 기대어 만들어요.","이것이 상호 의존이에요."]}'::jsonb),
('g6_2_soc_u2_review_c#9','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C1',2,'ox','auto','솔빛 신문 ①에서 소비자는 가게들의 경쟁 덕분에 더 좋은 딸기를 고를 수 있어요.',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"ox","stem":"솔빛 신문 ①에서 소비자는 가게들의 경쟁 덕분에 더 좋은 딸기를 고를 수 있어요.","answer":"O","reason_options":[{"t":"가게들이 손님을 끌려고 품질을 높이기 때문에","correct":true},{"t":"가게가 경쟁하면 딸기가 모두 사라지기 때문에","mis":"SO6-2-u2-X02"}],"mis":"SO6-2-u2-X02","explanation":["경쟁은 품질을 높여요.","소비자가 고를 수 있어요.","시장경제의 좋은 점이에요."],"asset":{"type":"passage","lines":["올해 마을에 딸기 농장이 늘어 시장에 딸기가 아주 많이 나왔다.","딸기를 사려는 사람은 지난해와 비슷하다.","딸기 가게들은 손님을 끌려고 더 달고 싱싱한 딸기를 내놓는다."],"title":"솔빛 신문 ① 딸기 시장"}}'::jsonb),
('g6_2_soc_u2_review_c#10','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C2',2,'ox','auto','솔빛 신문 ②를 보면 한 기업의 활동이 다른 기업과 가계에도 영향을 줘요.',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"ox","stem":"솔빛 신문 ②를 보면 한 기업의 활동이 다른 기업과 가계에도 영향을 줘요.","answer":"O","reason_options":[{"t":"공장의 일자리가 가계의 소득이 되고, 그 소득이 가게의 판매로 이어지기 때문에","correct":true},{"t":"기업의 활동은 그 기업 안에서만 끝나기 때문에","mis":"SO6-2-u2-X04"}],"mis":"SO6-2-u2-X04","explanation":["공장이 일손을 뽑았어요.","주민 소득이 늘었어요.","가게 손님도 늘었어요."],"asset":{"type":"passage","lines":["마을 빵 공장이 일손을 열 명 더 뽑았다.","일자리를 얻은 주민들은 받은 급여로 마을 가게에서 장을 본다.","가게 주인들은 손님이 늘었다며 반긴다."],"title":"솔빛 신문 ② 빵 공장"}}'::jsonb),
('g6_2_soc_u2_review_c#11','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C4',2,'match','auto','솔빛 신문 ④ 음료 회사의 노력과 그 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"match","stem":"솔빛 신문 ④ 음료 회사의 노력과 그 가치를 알맞게 이으세요.","pairs":[{"l":"유리병으로 바꾸기","r":"환경"},{"l":"무료 과학 교실","r":"사회"},{"l":"경영 내용 공개","r":"투명 경영"}],"mis":"SO6-2-u2-X09","explanation":["병을 다시 쓰는 것은 환경이에요.","지역 아이들을 돕는 것은 사회예요.","내용 공개는 투명 경영이에요."],"asset":{"type":"passage","lines":["마을 음료 회사가 플라스틱병 대신 다시 쓰는 유리병으로 바꾸었다.","마을 아이들을 위한 무료 과학 교실도 열었다.","회사는 해마다 경영 내용을 주민에게 공개한다."],"title":"솔빛 신문 ④ 음료 회사"}}'::jsonb),
('g6_2_soc_u2_review_c#12','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C5',2,'ox','auto','우리나라의 빠른 경제성장은 가계·기업·정부 가운데 한쪽만의 노력으로 이루어졌어요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"ox","stem":"우리나라의 빠른 경제성장은 가계·기업·정부 가운데 한쪽만의 노력으로 이루어졌어요.","answer":"X","reason_options":[{"t":"가계와 기업, 정부가 함께 노력했기 때문에","correct":true},{"t":"정부가 모든 일을 혼자 했기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["가계는 일하고 저축했어요.","기업은 생산하고 수출했어요.","정부는 계획하고 도왔어요."]}'::jsonb),
('g6_2_soc_u2_review_c#13','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C6',2,'ox','auto','솔빛 신문 ⑤의 마을처럼 경제성장은 좋은 점과 문제를 함께 가져올 수 있어요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"ox","stem":"솔빛 신문 ⑤의 마을처럼 경제성장은 좋은 점과 문제를 함께 가져올 수 있어요.","answer":"O","reason_options":[{"t":"소득과 시설은 늘었지만 개울 오염과 쓰레기도 함께 늘었기 때문에","correct":true},{"t":"경제성장은 좋은 점만 가져오기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["좋아진 점이 있어요.","문제도 생겼어요.","두 쪽을 함께 봐요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb),
('g6_2_soc_u2_review_c#14','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C8',2,'ox','auto','솔빛 신문 ⑥에서 규칙을 정했으니 사람들의 태도는 더 이상 중요하지 않아요.',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"ox","stem":"솔빛 신문 ⑥에서 규칙을 정했으니 사람들의 태도는 더 이상 중요하지 않아요.","answer":"X","reason_options":[{"t":"규칙이 있어도 공동의 이익을 생각하며 지키려는 태도가 있어야 약수를 지킬 수 있기 때문에","correct":true},{"t":"규칙만 있으면 저절로 모두 지키기 때문에","mis":"SO6-2-u2-X16"}],"mis":"SO6-2-u2-X16","explanation":["규칙은 필요해요.","지키려는 마음도 필요해요.","둘이 함께 자원을 지켜요."],"asset":{"type":"passage","lines":["마을 사람들이 함께 쓰는 뒷산 약수터가 있다.","몇몇이 큰 통으로 물을 마구 받아 가 약수가 말라 간다.","마을 회의에서 한 사람이 하루 두 병만 받기로 정했다."],"title":"솔빛 신문 ⑥ 약수터"}}'::jsonb),
('g6_2_soc_u2_review_c#15','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',2,'ox','auto','솔빛 신문 ⑦에서 마을 김 공장이 김을 판 거래는 김을 산 이웃 나라 쪽에서 보면 수입이에요.',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":15,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"ox","stem":"솔빛 신문 ⑦에서 마을 김 공장이 김을 판 거래는 김을 산 이웃 나라 쪽에서 보면 수입이에요.","answer":"O","reason_options":[{"t":"같은 거래라도 산 나라 쪽에서 보면 들여온 것이기 때문에","correct":true},{"t":"한 거래는 어느 쪽에서 보든 수출이기 때문에","mis":"SO6-2-u2-X17"}],"mis":"SO6-2-u2-X17","explanation":["마을 쪽 — 수출이에요.","이웃 나라 쪽 — 수입이에요.","보는 쪽을 먼저 정해요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb),
('g6_2_soc_u2_review_c#16','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C10',2,'ox','auto','사우디아라비아가 원유를 많이 수출하는 것은 땅속 자원이 풍부하기 때문이에요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"ox","stem":"사우디아라비아가 원유를 많이 수출하는 것은 땅속 자원이 풍부하기 때문이에요.","answer":"O","reason_options":[{"t":"원유 같은 자원이 많으면 남는 것을 다른 나라에 팔 수 있기 때문에","correct":true},{"t":"사우디아라비아는 반도체 기술이 가장 뛰어나기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["자원이 풍부해요.","자원을 수출해요.","조건이 무역 모습을 정해요."]}'::jsonb),
('g6_2_soc_u2_review_c#17','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',3,'mc','auto','기업이 다른 나라에 공장을 지을 때의 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":17,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"기업이 다른 나라에 공장을 지을 때의 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"세계 사람들은 값싸고 다양한 제품을 사고 그 나라 사람들은 일자리를 얻지만, 정당한 임금과 환경 문제를 살펴야 한다","correct":true},{"t":"그 나라 사람들은 아무 이익도 얻지 못한다","mis":"SO6-2-u2-X20"},{"t":"좋은 점만 있고 살필 것은 없다","mis":"SO6-2-u2-X20"},{"t":"제품 가격이 반드시 비싸진다","mis":"SO6-2-u2-X20"}],"explanation":["일자리와 값싼 제품이 생겨요.","임금·환경 문제가 생길 수 있어요.","정당한 분배가 중요해요."]}'::jsonb),
('g6_2_soc_u2_review_c#18','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',3,'mc','auto','나라와 나라가 무역으로 서로 의존한다는 것을 가장 잘 보여 주는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X20']::text[],false,'{"seq":18,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"나라와 나라가 무역으로 서로 의존한다는 것을 가장 잘 보여 주는 것은 어느 것인가요?","options":[{"t":"우리나라는 흑연을 사 와 배터리를 만들고, 흑연을 판 나라는 그 배터리를 단 전기차를 사 간다","correct":true},{"t":"한 나라가 모든 물자를 스스로 만든다","mis":"SO6-2-u2-X18"},{"t":"여러 나라가 첨단 기술을 먼저 개발하려고 다툰다","mis":"SO6-2-u2-X20"},{"t":"나라끼리 무역을 끊는다","mis":"SO6-2-u2-X18"}],"explanation":["자원과 제품이 오가요.","서로가 서로의 손님이에요.","이것이 상호 의존이에요."],"asset":{"type":"passage","lines":["과거 — 우리나라는 흑연을 많이 캐는 나라였다.","그 뒤 — 다른 나라에서 값싼 흑연을 수입하며 거의 캐지 않게 되었다.","오늘날 — 수입한 흑연으로 전기차 배터리를 만들어 수출한다.","흑연을 캐는 나라는 그 배터리를 단 전기차를 수입하기도 한다."],"title":"흑연과 배터리"}}'::jsonb),
('g6_2_soc_u2_review_c#19','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',3,'error','auto','무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"error","stem":"무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유찬 — 「무역은 물건이 하나도 없을 때만 하는 거야.」","correct":true,"mis_target":"SO6-2-u2-X18"},{"t":"아린 — 「더 싸거나 좋은 물건을 사 오려고도 무역을 해.」","mis":"SO6-2-u2-X18"},{"t":"로운 — 「잘 만드는 것을 팔고 모자란 것을 사 와.」","mis":"SO6-2-u2-X18"}],"explanation":["있어도 더 싸면 사 와요.","잘 만드는 것은 팔아요.","서로 이익이 되어 무역해요."]}'::jsonb),
('g6_2_soc_u2_review_c#20','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C8',3,'ox','auto','같은 방안들이라도 어떤 기준을 더 중요하게 보느냐에 따라 가장 높은 방안이 달라질 수 있어요.',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"ox","stem":"같은 방안들이라도 어떤 기준을 더 중요하게 보느냐에 따라 가장 높은 방안이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"기준의 무게가 바뀌면 방안마다 합계가 달라지기 때문에","correct":true},{"t":"방안의 점수는 기준과 상관없이 언제나 같기 때문에","mis":"SO6-2-u2-X15"}],"mis":"SO6-2-u2-X15","explanation":["기준의 무게가 결과를 바꿔요.","점수판에서 확인했어요.","그래서 기준이 중요해요."],"asset":{"type":"passage","lines":["해결하고 싶은 문제 — 자원 낭비(재활용 쓰레기가 넘침)","방안 ㉠ 분리배출 캠페인 — 실천 3 · 효과 1 · 비용 3","방안 ㉡ 재활용 공장 새로 짓기 — 실천 1 · 효과 3 · 비용 1","방안 ㉢ 다회용기 쓰는 가게에 혜택 — 실천 2 · 효과 3 · 비용 1","점수는 1~3, 비용은 적게 들수록 높은 점수"],"title":"모둠 해결 방안 점수판"}}'::jsonb),
('g6_2_soc_u2_review_c#21','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',3,'ox','auto','수입이 늘어 국내 산업이 어려울 때는 관세를 높이거나 수입을 제한하기도 해요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"ox","stem":"수입이 늘어 국내 산업이 어려울 때는 관세를 높이거나 수입을 제한하기도 해요.","answer":"O","reason_options":[{"t":"국내 산업이 자랄 시간을 주고 경쟁력을 지키려는 방법이기 때문에","correct":true},{"t":"관세는 수출품에만 매기기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["관세와 수입 제한은 보호 방법이에요.","철강 산업이 그렇게 자랐어요.","부담도 함께 생각해요."]}'::jsonb),
('g6_2_soc_u2_review_c#22','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C12',3,'ox','auto','기업 소개 잡지 표지에 이윤만 적기보다 사회적 책임 목표와 근로자를 위한 노력을 함께 적으면 기업의 특징이 더 잘 드러나요.',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C12","difficulty":3,"kind":"ox","stem":"기업 소개 잡지 표지에 이윤만 적기보다 사회적 책임 목표와 근로자를 위한 노력을 함께 적으면 기업의 특징이 더 잘 드러나요.","answer":"O","reason_options":[{"t":"기업이 무엇을 중요하게 여기는지가 함께 보이기 때문에","correct":true},{"t":"잡지 표지에는 이윤 말고는 적을 수 없기 때문에","mis":"SO6-2-u2-X21"}],"mis":"SO6-2-u2-X21","explanation":["이윤만으로는 특징이 흐려요.","책임과 노력이 기업을 보여 줘요.","네 칸을 모두 채워요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb),
('g6_2_soc_u2_review_c#23','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',4,'mc','auto','솔빛 신문 ⑦과 ⑧을 함께 볼 때 마을 김 공장의 처지를 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X17','SO6-2-u2-X20']::text[],false,'{"seq":23,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"mc","stem":"솔빛 신문 ⑦과 ⑧을 함께 볼 때 마을 김 공장의 처지를 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"이웃 나라에 김을 팔며 의존하는 한편, 값싼 수입 김과 경쟁해야 한다","correct":true},{"t":"무역과 아무 관계가 없다","mis":"SO6-2-u2-X18"},{"t":"수입만 하고 수출은 하지 않는다","mis":"SO6-2-u2-X17"},{"t":"다른 나라와 경쟁할 필요가 없다","mis":"SO6-2-u2-X20"}],"explanation":["⑦ — 김을 팔고 기계를 사 와요.","⑧ — 수입 김과 경쟁해요.","의존과 경쟁이 함께 있어요."],"asset":{"type":"passage","lines":["이웃 나라의 값싼 김이 많이 들어와 마을 김 공장의 판매가 줄었다.","정부는 수입 김에 매기는 세금을 높일지 의논하고 있다.","마을 김 공장은 더 맛있는 김을 개발하려고 애쓴다."],"title":"솔빛 신문 ⑧ 값싼 김"}}'::jsonb),
('g6_2_soc_u2_review_c#24','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C7',4,'essay','teacher','솔빛 신문 ⑤의 마을이 겪은 경제성장의 긍정적인 영향과 문제를 하나씩 쓰고, 문제를 해결하려면 마을 주민·기업·정부가 각각 무엇을 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C7","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑤의 마을이 겪은 경제성장의 긍정적인 영향과 문제를 하나씩 쓰고, 문제를 해결하려면 마을 주민·기업·정부가 각각 무엇을 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 주민 소득이 늘고 큰 병원과 도서관이 생긴 것은 긍정적인 영향이다. 그러나 개울이 탁해지고 쓰레기가 늘어난 환경 문제가 생겼다. 주민은 분리배출을 잘하고 다회용기를 쓰며, 공장은 폐수를 깨끗하게 처리하는 시설을 갖추고, 정부는 오염 물질을 내보내는 기업에 벌금을 물리는 제도를 만들면 좋겠다.","scoring_points":["긍정적인 영향을 썼는가","문제를 썼는가","주민·기업·정부의 노력을 각각 썼는가"]},"explanation":["좋은 점과 문제를 함께 봐요.","문제는 환경이에요.","모두 함께 노력해요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb),
('g6_2_soc_u2_review_c#25','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C3',4,'essay','teacher','솔빛 신문 ③을 보고 근로자들이 누린 권리를 쓰고, 근로자의 권리를 법과 제도로 보호해야 하는 까닭을 근로자와 기업의 관계를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"essay","stem":"솔빛 신문 ③을 보고 근로자들이 누린 권리를 쓰고, 근로자의 권리를 법과 제도로 보호해야 하는 까닭을 근로자와 기업의 관계를 들어 쓰세요.","answer_guide":{"answer":"예: 근로자들은 근로자 단체를 통해 공장과 근로 조건을 협의하는 권리를 누렸다. 근로자가 기업에 제공하는 노동력은 경제활동에서 중요한 역할을 하고, 근로자와 기업은 서로 의존하는 관계이다. 그런데 근로자 한 사람의 목소리는 기업보다 작으므로 법과 제도가 권리를 보장해야 근로자와 기업이 대등하게 협의할 수 있다.","scoring_points":["협의(단체) 권리를 썼는가","근로자와 기업이 서로 의존함을 썼는가","법과 제도가 필요한 까닭을 썼는가"]},"explanation":["단체를 통해 협의했어요.","근로자와 기업은 서로 의존해요.","법이 대등한 협의를 받쳐 줘요."],"asset":{"type":"passage","lines":["빵 공장 근로자들이 근로자 단체를 통해 쉬는 시간을 늘려 달라고 했다.","공장과 근로자가 마주 앉아 이야기한 끝에 휴게실을 넓히기로 했다.","근로자들은 더 즐겁게 일하게 되었다고 말했다."],"title":"솔빛 신문 ③ 휴게실"}}'::jsonb),
