('g6_2_soc_u2_review_d#18','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C4',3,'ox','auto','기업이 사회적 책임을 다해야 하는 것도 기업과 사회가 서로 영향을 주고받기 때문이에요.',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":18,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"ox","stem":"기업이 사회적 책임을 다해야 하는 것도 기업과 사회가 서로 영향을 주고받기 때문이에요.","answer":"O","reason_options":[{"t":"기업의 활동이 사회에 큰 영향을 주고, 사회의 믿음이 기업의 성장에도 이어지기 때문에","correct":true},{"t":"기업과 사회는 서로 아무 영향도 주지 않기 때문에","mis":"SO6-2-u2-X07"}],"mis":"SO6-2-u2-X07","explanation":["기업은 사회 안에 있어요.","사회에 영향을 줘요.","사회의 믿음이 기업을 키워요."]}'::jsonb),
('g6_2_soc_u2_review_d#19','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',3,'error','auto','우리나라 무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"error","stem":"우리나라 무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「우리나라는 원유를 캐서 다른 나라에 많이 팔아.」","correct":true,"mis_target":"SO6-2-u2-X19"},{"t":"보민 — 「우리나라는 원유를 사 와서 석유 제품을 만들어 팔아.」","mis":"SO6-2-u2-X19"},{"t":"하민 — 「반도체는 우리나라의 주요 수출품이야.」","mis":"SO6-2-u2-X19"}],"explanation":["우리나라는 원유를 수입해요.","석유 제품은 수출해요.","원유와 석유 제품은 달라요."]}'::jsonb),
('g6_2_soc_u2_review_d#20','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',3,'mc','auto','빠른 경제성장으로 생긴 문제를 해결하려는 정부의 노력으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"빠른 경제성장으로 생긴 문제를 해결하려는 정부의 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"더 나은 일자리를 위한 제도와 정책을 만든다","correct":true},{"t":"문제를 개인에게만 맡긴다","mis":"SO6-2-u2-X15"},{"t":"기업과 근로자 사이의 일에 나서지 않는다","mis":"SO6-2-u2-X15"},{"t":"쓰레기를 더 많이 버리게 한다","mis":"SO6-2-u2-X15"}],"explanation":["정부는 제도와 정책을 만들어요.","기업·근로자는 소통해요.","시민도 함께 노력해요."]}'::jsonb),
('g6_2_soc_u2_review_d#21','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',3,'mc','auto','여러 나라가 다른 나라의 큰 시설 공사를 따내려고 경쟁하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"여러 나라가 다른 나라의 큰 시설 공사를 따내려고 경쟁하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 이익을 얻고 뛰어난 기술을 세계에 알릴 수 있기 때문에","correct":true},{"t":"공사를 하면 손해만 보기 때문에","mis":"SO6-2-u2-X20"},{"t":"다른 나라와 의존하지 않으려고","mis":"SO6-2-u2-X20"},{"t":"관세를 내지 않으려고","mis":"SO6-2-u2-X20"}],"explanation":["시설 공사는 큰 이익이에요.","기술도 알릴 수 있어요.","그래서 서로 경쟁해요."]}'::jsonb),
('g6_2_soc_u2_review_d#22','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C12',3,'mc','auto','수출하고 싶은 나라를 고를 때 가장 먼저 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C12","difficulty":3,"kind":"mc","stem":"수출하고 싶은 나라를 고를 때 가장 먼저 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"그 나라의 특징과 현황을 조사한다","correct":true},{"t":"이름이 마음에 드는 나라를 고른다","mis":"SO6-2-u2-X21"},{"t":"가장 먼 나라를 고른다","mis":"SO6-2-u2-X21"},{"t":"우리 상품이 필요 없는 나라를 고른다","mis":"SO6-2-u2-X21"}],"explanation":["상품이 필요할 나라를 찾아요.","조사한 내용이 근거예요.","고른 까닭을 발표해요."]}'::jsonb),
('g6_2_soc_u2_review_d#23','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C7',4,'mc','auto','솔빛 신문 ⑤의 마을과 ⑥의 약수터를 함께 볼 때 마을이 지속적으로 발전하려면 무엇이 필요할까요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X16']::text[],false,'{"seq":23,"concept":"SO6-2-u2-C7","difficulty":4,"kind":"mc","stem":"솔빛 신문 ⑤의 마을과 ⑥의 약수터를 함께 볼 때 마을이 지속적으로 발전하려면 무엇이 필요할까요?","options":[{"t":"성장으로 얻은 것은 살리되 함께 쓰는 자원과 환경을 지키는 규칙과 태도를 갖춘다","correct":true},{"t":"개발을 멈추고 병원과 도서관을 없앤다","mis":"SO6-2-u2-X12"},{"t":"쓰레기와 오염은 그냥 둔다","mis":"SO6-2-u2-X12"},{"t":"약수를 먼저 받는 사람이 다 가져간다","mis":"SO6-2-u2-X16"}],"explanation":["성장의 열매를 지켜요.","자원과 환경도 지켜요.","규칙과 태도가 함께 필요해요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb),
('g6_2_soc_u2_review_d#24','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',4,'essay','teacher','솔빛 신문 ⑥의 약수터 이야기에 담긴 현상의 이름을 쓰고, 마을 회의의 규칙만으로 충분한지 자기 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑥의 약수터 이야기에 담긴 현상의 이름을 쓰고, 마을 회의의 규칙만으로 충분한지 자기 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 함께 쓰는 자원을 몇몇이 자기 이익만 생각하며 써서 모두가 피해를 보는 공유지의 비극이다. 하루 두 병이라는 규칙은 꼭 필요하지만 그것만으로는 충분하지 않다. 사람들이 규칙을 몰래 어기면 약수는 다시 마를 것이므로, 약수가 모두의 것이라는 생각으로 공동의 이익을 지키려는 태도가 함께 있어야 한다.","scoring_points":["공유지의 비극이라고 썼는가","규칙의 필요성을 썼는가","규칙과 함께 태도가 필요하다는 생각을 까닭과 썼는가"]},"explanation":["함께 쓰는 자원이에요.","규칙은 울타리예요.","지키려는 마음이 함께 필요해요."],"asset":{"type":"passage","lines":["마을 사람들이 함께 쓰는 뒷산 약수터가 있다.","몇몇이 큰 통으로 물을 마구 받아 가 약수가 말라 간다.","마을 회의에서 한 사람이 하루 두 병만 받기로 정했다."],"title":"솔빛 신문 ⑥ 약수터"}}'::jsonb),
('g6_2_soc_u2_review_d#25','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C12',4,'essay','teacher','솔빛 신문 ⑦의 김 공장 대표가 되었다고 생각하고 기업 운영 계획을 세워 보세요. 대표 상품, 주요 수출국과 고른 까닭, 사회적 책임 목표, 근로자를 위한 노력을 차례로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C12","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑦의 김 공장 대표가 되었다고 생각하고 기업 운영 계획을 세워 보세요. 대표 상품, 주요 수출국과 고른 까닭, 사회적 책임 목표, 근로자를 위한 노력을 차례로 쓰세요.","answer_guide":{"answer":"예: 대표 상품은 깨끗한 바다에서 기른 바삭한 구운 김이다. 김밥과 한국 음식을 즐기는 사람이 늘고 있는 나라를 조사해 그 나라를 주요 수출국으로 고르겠다. 목표는 「바다를 깨끗하게 지키며 매년 성장하는 김 공장」으로, 김을 기르는 바다의 쓰레기를 치우겠다. 근로자에게는 휴가를 보장하고 매주 대화의 시간을 가지겠다.","scoring_points":["대표 상품을 정했는가","수출국과 고른 까닭을 썼는가","사회적 책임 목표와 근로자를 위한 노력을 썼는가"]},"explanation":["상품 → 수출국 → 목표 → 노력이에요.","수출국은 조사해 골라요.","책임과 근로자를 함께 담아요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO6-2-u3-C1','soc',6,2,'u3',1,'인구 분포에 영향을 주는 요인 — 기온·강수량·지형 등 자연환경과 산업·교통·문화 등 인문환경이 인구 분포에 많은 영향을 줌 · 옛날에는 기후가 온화한 지역·평야·해안처럼 자연환경이 유리한 곳에, 오늘날에는 산업이 발달해 일자리가 풍부하고 교통이 편리하며 교육·문화 시설이 갖춰진 곳에 모여 삶',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],1),
('SO6-2-u3-C2','soc',6,2,'u3',1,'세계의 인구 분포 특징 — 세계 인구는 고르게 분포하지 않고 특정 지역에 모여 있음 · 세계 인구의 약 90 %가 육지가 많은 북반구에, 기후가 온화한 중위도에 많고 냉대·한대 기후의 고위도에 적음 · 동아시아와 남부 아시아(온화한 평야·농업)·서부 유럽(산업·일자리·교통)에 많고, 사하라 사막(강수량 매우 적음)·알래스카(기온 매우 낮음)·열대 우림에 적음 · 100명 마을이면 아시아 59명·오세아니아 1명 · 세계 인구는 약 25억 명(1950)에서 약 81억 명(2023)으로 늘고 아프리카 비율이 크게 늘었음(비율이 줄어도 수가 준 것은 아님)',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],2),
('SO6-2-u3-C3','soc',6,2,'u3',2,'세계 여러 나라의 인구수 — 나라마다 다르며 대체로 아시아의 나라들은 많고 오세아니아의 나라들은 적음(10억 명 이상은 인도·중국) · 면적이 넓다고 반드시 인구수가 많은 것은 아님 · 인도(강수량 많고 비옥한 토양·농업·높은 출생률), 미국(온화한 기후·다양한 산업·이민), 리비아(국토 대부분 사막이라 면적에 비해 적음), 투발루(작은 섬나라, 기후변화로 잠길 위험) · 인구 성장률은 인구가 증가하는 비율로 아프리카는 높고 유럽은 낮거나 감소 · 인구수는 출생·사망·인구의 이동·환경 변화에 따라 달라짐',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],3),
('SO6-2-u3-C4','soc',6,2,'u3',3,'세계 여러 나라의 인구 밀도 — 일정한 면적(1 km²) 안에 사는 인구수로 인구가 모여 있는 정도를 나타냄, 면적에 비해 인구수가 많을수록 높음 · 방글라데시·르완다·인도는 높고 몽골·오스트레일리아·캐나다는 낮음, 아시아·유럽에 높은 나라가 많고 고위도에 낮은 나라가 많음 · 방글라데시(약 1,317명/km², 국토 대부분 평야·온화한 기후·벼농사) vs 캐나다(약 4명/km², 냉대 기후라 농사지을 땅이 적음) · 우리나라(약 515명/km²)는 면적이 비슷한 나라보다 매우 높은 편 · 인구가 늘면 밀도도 높아지는 등 변화할 수 있음',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],4),
('SO6-2-u3-C5','soc',6,2,'u3',4,'인구 구조와 인구 피라미드 — 인구 구조는 연령·성 등을 기준으로 한 인구의 짜임새(유소년층 0~14세·청장년층 15~64세·노년층 65세 이상) · 인구 피라미드는 연령별·성별 인구를 나타낸 그래프(가로축 왼쪽 남자·오른쪽 여자 비율, 세로축 나이) · 세계 인구 구조는 1960년보다 2020년에 유소년층 비율이 줄고 노년층 비율이 늘었으며 청장년층 비율이 가장 높음 · 출생률·사망률이 높고 평균 수명이 짧으면 유소년층이 많고(나이지리아), 낮고 길면 노년층이 많음(일본)',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],5),
('SO6-2-u3-C6','soc',6,2,'u3',4,'인구 구조와 우리 생활 — 인구 구조로 미래 인구 변화를 예상할 수 있고 경제·문화 등 생활과 밀접함 · 유소년층이 많은 나라는 유치원·학교 같은 어린이 시설, 노년층이 많은 나라는 요양원·노인 복지 센터가 더 필요함 · 청장년층 비율이 높은 인도네시아는 젊은 소비자가 많아 기업이 주목하는 「젊은 시장」 · 석유 자원이 풍부한 사우디아라비아·아랍 에미리트 등은 외국인 근로자를 받아들여 청장년층이 두드러지게 많음 · 아이를 더 낳거나 덜 낳도록 권하는 포스터도 인구 구조와 관련',ARRAY['[6사12-01] 세계의 인구 분포와 인구 특징(수·밀도·구조)']::text[],6),
('SO6-2-u3-C7','soc',6,2,'u3',5,'지구촌과 지구촌을 위협하는 문제 — 지구촌은 과학 기술과 교통·통신의 발달로 지구가 하나의 마을처럼 가까워진 모습(소식·정보·문화 교류가 쉬워진 좋은 점, 한 나라의 문제가 다른 나라에 영향을 주고 갈등이 생길 수 있는 문제점) · 지구촌은 자원과 에너지 고갈(광산 개발), 생태계 파괴(열대 우림 벌채 — 농사·목축·산업 등 인간 활동이 원인, 동식물의 터전과 탄소 흡수가 사라짐), 기후변화(화석 연료 과다 사용 — 녹는 빙하), 난민(전쟁·재난으로 살던 곳을 떠남) 문제를 겪음 · 지구촌 전등 끄기 캠페인처럼 함께 노력함',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],7),
('SO6-2-u3-C8','soc',6,2,'u3',6,'지구촌 문제 조사하기 — 문제 생각하기 → 조사 방법 정하기 → 문제 상황·원인 조사하기 → 내용 정리하기 · 자료는 누리집 통계·책·신문 기사·카드 뉴스·다큐멘터리, 출처가 명확하고 믿을 만한지 확인 · 붙임쪽지에 지역·문제 상황·문제 원인을 요약해 세계지도의 해당 나라에 붙이면 지구촌 곳곳의 문제를 한눈에 파악 · 탄소를 적게 내는 나라가 가뭄을 겪고(동아프리카), 해수면 상승으로 섬이 잠기는(투발루) 것처럼 지구촌 문제는 한 지역에 그치지 않는 우리 모두의 문제 · 옷 한 벌에도 많은 물이 들어 내 작은 행동이 지구에 영향을 줌',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],8),
('SO6-2-u3-C9','soc',6,2,'u3',7,'지속가능한 미래와 개인·기업·국가의 노력 — 지속가능한 미래는 오늘날의 모든 사람이 지구 환경을 개선하고 보존해 미래 세대에 물려주려는 노력 속에서 이루어짐(인간 위주가 아니라 지구촌 모두를 생각하는 자세) · 개인: 녹색 제품 소비(생산 때 자원·에너지를 적게 써 오염 물질 최소화), 일회용품 줄이기, 분리배출·재활용, 에너지 절약 · 기업: 탄소를 줄이는 제품·친환경 소재·자원을 적게 쓴 제품(라벨 없앤 생수병), 책임 있는 경영 · 국가: 법과 제도·정책, 국제 협약 준수(기후변화 협약), 난민 보호 · 여러 주체의 노력이 모두 모여야 함',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],9),
('SO6-2-u3-C10','soc',6,2,'u3',7,'국제기구와 비정부 기구의 노력 — 국제기구: 국제 연합(국제 평화와 안전·협력), 국제 연합 아동 기금(어려운 어린이에게 의료·식량·교육), 국제 연합 난민 기구(난민 보호·물품·의료·교육) · 비정부 기구는 개인이나 민간단체가 중심이 되어 공공의 이익을 지키려고 만든 단체: 국경 없는 의사회(차별 없는 의료), 세계 자연 기금(생물 다양성·기후변화 대응), 그린피스(환경 연구·해양 생태계 보호)',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],10),
('SO6-2-u3-C11','soc',6,2,'u3',8,'세계시민과 실천 — 세계시민은 지구촌의 지속가능한 미래를 위해 협력하며 책임 있게 행동하는 사람으로, 지구촌 문제를 우리 모두의 문제로 여기고 관심을 두며 해결 방법을 고민함 · 할 일을 정할 때 일상에서 실천 가능한지·효과가 있는지 생각하고 더하기(+) 노력(장바구니·다회용품)과 빼기(−) 노력(플라스틱 덜 쓰기·안 쓰는 전등 끄기)을 구분 · 실천 인증 릴레이: 인증 사진 → 구체적 기록 → 다음 친구에게 알리기 · 개인의 노력이 기업과 사회의 변화를 만들 수 있음 · 주제를 정할 때 서로 다른 관심을 존중 · 에코 제품 디자이너처럼 직업으로도 이바지',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],11),
('SO6-2-u3-C12','soc',6,2,'u3',9,'그림책 스토리보드 만들기 — 스토리보드는 장면을 구성하며 이야기의 흐름을 작성한 것으로 장면별 줄거리와 스케치 형식의 그림(그림 순서·그림·그림 설명·글·대사 칸)이 들어감 · 계획: 주제·줄거리, 독자를 정하고 그 수준에 맞게(어린 독자면 쉬운 낱말·짧은 문장), 세계 인구의 특징과 지속가능한 지구촌이 골고루 드러나게, 이야기 흐름이 자연스럽게 · 역할을 나누어 만들고 발표회에서 내용과 수준이 적절한지, 계획대로 만들었는지 살펴봄',ARRAY['[6사12-02] 지구촌 문제와 지속가능한 미래를 위한 노력·세계시민']::text[],12)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO6-2-u3-X01','soc',6,'u3',ARRAY['SO6-2-u3-C1']::text[],'인구 분포에 영향을 주는 자연환경 요인(기온·강수량·지형)과 인문환경 요인(산업·교통·문화)을 바꾸어 나눈다','자연이 만든 것 · 사람이 만든 것'),
('SO6-2-u3-X02','soc',6,'u3',ARRAY['SO6-2-u3-C1','SO6-2-u3-C2']::text[],'세계 인구가 고르게 퍼져 있다고, 또는 땅이 넓은 곳일수록 사람이 많다고 여긴다','특정한 지역에 모여 있어요'),
('SO6-2-u3-X03','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구가 많은 지역과 적은 지역, 그 까닭을 바꾸어 짝짓는다(알래스카·사하라에 많다고, 서부 유럽은 기후 탓에 적다고 하는 등)','점이 빽빽한 곳과 드문 곳의 환경'),
('SO6-2-u3-X04','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구가 많은 반구와 위도를 거꾸로 안다(남반구·고위도에 많다고)','북반구 약 90 % · 온화한 중위도'),
('SO6-2-u3-X05','soc',6,'u3',ARRAY['SO6-2-u3-C2']::text[],'인구 비율과 인구수를 같은 것으로 여기거나(비율이 줄면 수도 줄었다고) 세계 인구의 변화를 거꾸로 읽는다','비율 ≠ 인구수'),
('SO6-2-u3-X06','soc',6,'u3',ARRAY['SO6-2-u3-C3','SO6-2-u3-C4']::text[],'나라의 면적이 넓으면 인구수도 많다고 여긴다','넓어도 살기 어려우면 적어요'),
('SO6-2-u3-X07','soc',6,'u3',ARRAY['SO6-2-u3-C3']::text[],'대륙·나라별 인구수의 많고 적음과 그 까닭을 바꾸어 안다(오세아니아에 인구가 많다고, 리비아가 사막 때문에 인구가 많다고 하는 등)','아시아는 많고 오세아니아는 적어요'),
('SO6-2-u3-X08','soc',6,'u3',ARRAY['SO6-2-u3-C3']::text[],'인구 성장률의 뜻이나 인구수를 바꾸는 요인(출생·사망·이동·환경 변화)을 잘못 안다','늘어나는 비율 · 들어오고 나가고 태어나고 사망하고'),
('SO6-2-u3-X09','soc',6,'u3',ARRAY['SO6-2-u3-C4']::text[],'인구 밀도를 인구수만으로, 또는 면적만으로 판단한다','1 km² 안의 인구수'),
('SO6-2-u3-X10','soc',6,'u3',ARRAY['SO6-2-u3-C4']::text[],'인구 밀도가 높은 나라와 낮은 나라, 그 까닭(평야·벼농사 / 냉대 기후)을 바꾸어 안다','방글라데시 높음 · 캐나다 낮음'),
('SO6-2-u3-X11','soc',6,'u3',ARRAY['SO6-2-u3-C5']::text[],'인구 구조의 뜻이나 인구 피라미드의 축(가로 — 남녀 비율, 세로 — 나이)·연령층을 잘못 읽는다','아래층 유소년 · 위층 노년'),
('SO6-2-u3-X12','soc',6,'u3',ARRAY['SO6-2-u3-C5']::text[],'출생률·사망률·평균 수명과 인구 구조의 관계를 거꾸로 안다(출생률이 낮은 나라에 유소년층이 많다고 하는 등)','낮은 출생률 → 노년층 비율 높음'),
('SO6-2-u3-X13','soc',6,'u3',ARRAY['SO6-2-u3-C6']::text[],'인구 구조와 생활(필요한 시설·젊은 시장·외국인 근로자)을 맞지 않게 잇는다','많은 연령층에 맞는 시설과 시장'),
('SO6-2-u3-X14','soc',6,'u3',ARRAY['SO6-2-u3-C7']::text[],'지구촌의 뜻을 오해하거나 지구촌 시대의 좋은 점과 문제점을 바꾸어 안다','하나의 마을처럼 가까워진 지구'),
('SO6-2-u3-X15','soc',6,'u3',ARRAY['SO6-2-u3-C7','SO6-2-u3-C8']::text[],'지구촌 문제(자원·에너지 고갈, 생태계 파괴, 기후변화, 난민)와 그 장면·원인을 바꾸어 짝짓는다','광산 · 열대 우림 · 빙하 · 보트'),
('SO6-2-u3-X16','soc',6,'u3',ARRAY['SO6-2-u3-C7','SO6-2-u3-C8','SO6-2-u3-C11']::text[],'지구촌 문제를 그 나라만의 일로 여겨 나와 관계없다고 생각한다','우리 모두의 문제'),
('SO6-2-u3-X17','soc',6,'u3',ARRAY['SO6-2-u3-C8']::text[],'지구촌 문제를 조사할 때 출처를 확인하지 않거나, 지역·문제 상황·원인 가운데 일부를 빠뜨린다','믿을 만한 자료 · 지역·상황·원인'),
('SO6-2-u3-X18','soc',6,'u3',ARRAY['SO6-2-u3-C9']::text[],'지속가능한 미래를 지금 세대의 편리함만 생각하는 것으로, 또는 인간 위주로 생각하는 것으로 오해한다','미래 세대에 물려주기'),
('SO6-2-u3-X19','soc',6,'u3',ARRAY['SO6-2-u3-C9']::text[],'개인·기업·국가가 하는 노력을 서로 바꾸어 짝짓는다','생활 속 실천 · 제품 · 법과 협약'),
('SO6-2-u3-X20','soc',6,'u3',ARRAY['SO6-2-u3-C10']::text[],'국제기구와 비정부 기구를 헷갈리거나 각 단체가 하는 일을 바꾸어 안다','나라들이 만든 기구 · 민간이 만든 단체'),
('SO6-2-u3-X21','soc',6,'u3',ARRAY['SO6-2-u3-C11']::text[],'세계시민의 자세와 실천 방법을 잘못 안다(나 하나로는 소용없다고, 실천하기 어려운 계획을 세우거나 더하기·빼기 노력을 바꾸는 등)','작은 일부터 · 책임감 · 실천 가능하게'),
('SO6-2-u3-X22','soc',6,'u3',ARRAY['SO6-2-u3-C12']::text[],'그림책 스토리보드를 만들 때 독자의 수준·이야기의 흐름·단원 주제를 고려하지 않는다','누가 읽나 · 흐름 · 두 주제 골고루'),
('SO6-2-u3-X23','soc',6,'u3',ARRAY['SO6-2-u3-C2','SO6-2-u3-C3','SO6-2-u3-C4']::text[],'인구 공부를 나라별 인구수·수치를 외우는 것으로 여겨 자료에서 특징과 까닭을 읽어 내는 것을 놓친다','외우기보다 자료를 읽고 견주기')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
