('g6_2_soc_u3_L01_basic#2','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'mc','auto','100명 마을 자료에서 사람이 가장 많이 사는 대륙은 어디인가요?',ARRAY['SO6-2-u3-X07']::text[],false,'{"seq":2,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"mc","stem":"100명 마을 자료에서 사람이 가장 많이 사는 대륙은 어디인가요?","options":[{"t":"아시아","correct":true},{"t":"오세아니아","mis":"SO6-2-u3-X07"},{"t":"유럽","mis":"SO6-2-u3-X07"},{"t":"아프리카","mis":"SO6-2-u3-X07"}],"explanation":["가장 큰 수를 찾아요.","아시아에 59명이 살아요.","아시아가 가장 많아요."],"asset":{"type":"passage","lines":["세계가 100명이 사는 마을이라면 — 아시아 59명","아프리카 · 유럽 · 아메리카 대륙에 나머지가 산다.","오세아니아 1명 — 가장 적다."],"title":"100명 마을 자료(국제 연합 자료를 줄인 것)"}}'::jsonb),
('g6_2_soc_u3_L01_basic#3','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'sa','auto','세계 인구의 약 90 %가 사는 반구는 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"sa","stem":"세계 인구의 약 90 %가 사는 반구는 어디인가요? 세 글자로 쓰세요.","answer":["북반구"],"explanation":["육지가 많은 쪽이에요.","적도 위쪽이에요.","북반구예요."],"mis":"SO6-2-u3-X04"}'::jsonb),
('g6_2_soc_u3_L01_basic#4','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',1,'ox','auto','세계의 인구는 지구 곳곳에 고르게 분포해요.',ARRAY['SO6-2-u3-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u3-C2","difficulty":1,"kind":"ox","stem":"세계의 인구는 지구 곳곳에 고르게 분포해요.","answer":"X","reason_options":[{"t":"특정한 지역에 모여 있어 많은 곳과 적은 곳이 있기 때문에","correct":true},{"t":"모든 대륙에 똑같은 수의 사람이 살기 때문에","mis":"SO6-2-u3-X02"}],"mis":"SO6-2-u3-X02","explanation":["점이 빽빽한 곳이 있어요.","드문 곳도 있어요.","고르지 않아요."]}'::jsonb),
('g6_2_soc_u3_L01_basic#5','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'match','auto','지역과 인구가 많거나 적은 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"match","stem":"지역과 인구가 많거나 적은 까닭을 알맞게 이으세요.","pairs":[{"l":"동아시아와 남부 아시아","r":"온화한 평야에서 농업 발달"},{"l":"서부 유럽","r":"산업 발달·풍부한 일자리"},{"l":"사하라 사막","r":"강수량이 매우 적음"},{"l":"알래스카","r":"기온이 매우 낮음"}],"mis":"SO6-2-u3-X03","explanation":["평야와 산업이 있으면 많아요.","물이 없으면 적어요.","너무 추워도 적어요."]}'::jsonb),
('g6_2_soc_u3_L01_basic#6','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'mc','auto','돋보기로 본 네 지역 가운데 인구가 적은 까닭이 「기온이 매우 낮아 생활하기 어렵다」인 곳은 어디인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"돋보기로 본 네 지역 가운데 인구가 적은 까닭이 「기온이 매우 낮아 생활하기 어렵다」인 곳은 어디인가요?","options":[{"t":"㉱ 알래스카","correct":true},{"t":"㉰ 사하라 사막","mis":"SO6-2-u3-X03"},{"t":"㉯ 서부 유럽","mis":"SO6-2-u3-X03"},{"t":"㉮ 동아시아와 남부 아시아","mis":"SO6-2-u3-X03"}],"explanation":["고위도의 추운 곳이에요.","식물이 자라기 어려워요.","알래스카예요."],"asset":{"type":"passage","lines":["㉮ 동아시아와 남부 아시아 — 점이 빽빽하다.","㉯ 서부 유럽 — 점이 빽빽하다.","㉰ 사하라 사막 — 점이 드물다.","㉱ 알래스카 — 점이 드물다."],"title":"돋보기로 본 네 지역"}}'::jsonb),
('g6_2_soc_u3_L01_basic#7','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'mc','auto','인구가 많이 분포하는 위도와 그 까닭을 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X04','SO6-2-u3-X02']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"mc","stem":"인구가 많이 분포하는 위도와 그 까닭을 알맞게 말한 것은 어느 것인가요?","options":[{"t":"중위도 — 온대 기후처럼 온화한 기후가 나타나서","correct":true},{"t":"고위도 — 냉대·한대 기후가 나타나서","mis":"SO6-2-u3-X04"},{"t":"저위도 — 기온이 매우 높아서","mis":"SO6-2-u3-X04"},{"t":"세 위도에 똑같이 분포해서","mis":"SO6-2-u3-X02"}],"explanation":["온화한 기후가 열쇠예요.","생활하고 농사짓기 좋아요.","중위도에 많아요."]}'::jsonb),
('g6_2_soc_u3_L01_basic#8','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C1',2,'mc','auto','오늘날 사람들이 많이 모여 사는 곳의 특징으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u3-C1","difficulty":2,"kind":"mc","stem":"오늘날 사람들이 많이 모여 사는 곳의 특징으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산업이 발달해 일자리가 풍부하고 교통이 편리한 곳","correct":true},{"t":"강수량이 매우 적은 사막","mis":"SO6-2-u3-X03"},{"t":"기온이 매우 낮은 극지방","mis":"SO6-2-u3-X03"},{"t":"열대 우림이 우거진 곳","mis":"SO6-2-u3-X03"}],"explanation":["오늘날엔 인문환경이 중요해요.","일자리와 교통을 찾아요.","그런 곳에 모여요."]}'::jsonb),
('g6_2_soc_u3_L01_basic#9','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',2,'ox','auto','세계 인구는 1950년 약 25억 명에서 2023년 약 81억 명으로 크게 늘었어요.',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":9,"concept":"SO6-2-u3-C2","difficulty":2,"kind":"ox","stem":"세계 인구는 1950년 약 25억 명에서 2023년 약 81억 명으로 크게 늘었어요.","answer":"O","reason_options":[{"t":"대륙별 세계 인구의 변화 자료에서 세계 인구가 늘었음을 읽을 수 있기 때문에","correct":true},{"t":"세계 인구는 1950년보다 줄어들었기 때문에","mis":"SO6-2-u3-X05"}],"mis":"SO6-2-u3-X05","explanation":["25억에서 81억이에요.","세 배 넘게 늘었어요.","인구가 크게 늘었어요."],"asset":{"type":"passage","lines":["세계 인구 — 1950년 약 25억 명 → 2023년 약 81억 명","세계 인구에서 차지하는 비율이 늘어난 대륙 — 아프리카(크게)·아시아 등","세계 인구에서 차지하는 비율이 줄어든 대륙 — 유럽·북아메리카"],"title":"대륙별 세계 인구의 변화"}}'::jsonb),
('g6_2_soc_u3_L01_basic#10','soc',6,2,'u3','L01','g6_2_soc_u3_L01_basic','lesson_basic','SO6-2-u3-C2',3,'mc','auto','세계 인구에서 유럽이 차지하는 비율이 줄었어요. 이것을 바르게 해석한 것은 어느 것인가요?',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"세계 인구에서 유럽이 차지하는 비율이 줄었어요. 이것을 바르게 해석한 것은 어느 것인가요?","options":[{"t":"세계 인구 가운데 유럽이 차지하는 몫이 작아진 것이지, 유럽 인구수가 반드시 줄었다는 뜻은 아니다","correct":true},{"t":"유럽의 인구수가 반드시 줄었다","mis":"SO6-2-u3-X05"},{"t":"유럽의 면적이 좁아졌다","mis":"SO6-2-u3-X05"},{"t":"세계 인구가 줄었다","mis":"SO6-2-u3-X05"}],"explanation":["비율과 인구수는 달라요.","전체가 크게 늘었어요.","몫이 작아진 거예요."],"asset":{"type":"passage","lines":["세계 인구 — 1950년 약 25억 명 → 2023년 약 81억 명","세계 인구에서 차지하는 비율이 늘어난 대륙 — 아프리카(크게)·아시아 등","세계 인구에서 차지하는 비율이 줄어든 대륙 — 유럽·북아메리카"],"title":"대륙별 세계 인구의 변화"}}'::jsonb),
