('g6_2_soc_u3_L01_challenge#7','soc',6,2,'u3','L01','g6_2_soc_u3_L01_challenge','lesson_challenge','SO6-2-u3-C2',3,'mc','auto','대륙별 세계 인구의 변화 자료에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u3-X05']::text[],false,'{"seq":7,"concept":"SO6-2-u3-C2","difficulty":3,"kind":"mc","stem":"대륙별 세계 인구의 변화 자료에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"세계 인구가 크게 늘었고 아프리카가 차지하는 비율이 크게 늘었다","correct":true},{"t":"모든 대륙의 비율이 똑같이 늘었다","mis":"SO6-2-u3-X05"},{"t":"세계 인구는 그대로이다","mis":"SO6-2-u3-X05"},{"t":"유럽의 비율이 가장 크게 늘었다","mis":"SO6-2-u3-X05"}],"explanation":["25억에서 81억으로 늘었어요.","아프리카 몫이 커졌어요.","유럽 몫은 줄었어요."],"asset":{"type":"passage","lines":["세계 인구 — 1950년 약 25억 명 → 2023년 약 81억 명","세계 인구에서 차지하는 비율이 늘어난 대륙 — 아프리카(크게)·아시아 등","세계 인구에서 차지하는 비율이 줄어든 대륙 — 유럽·북아메리카"],"title":"대륙별 세계 인구의 변화"}}'::jsonb),
